        'evidence_followups_desc' => 'தொடர் நடவடிக்கை என்பது ஒரு பணியின் வேலை பார்வையிலிருந்து, அது கண்டறிந்ததைச் சரிசெய்ய உருவாக்கப்படும் டிக்கெட் அல்லது பணி. பணியை முடிப்பது என்றால் சரிபார்ப்பு செய்யப்பட்டு அதன் கண்டுபிடிப்புகள் பதிவாகிவிட்டன என்பதாகும், எனவே இயல்பாக திறந்த தொடர் நடவடிக்கை அதைத் தடுக்காது.',
        'evidence_access_anyone' => 'மீண்டும் நிகழும் பணியைப் பார்க்கக்கூடிய எவரும்',
        'evidence_access_permission' => '"சான்று அறிக்கையை இயக்கு" உள்ள பாத்திரங்கள் மட்டும்',
        'evidence_access_desc' => 'பணிகளுக்கு படிக்க மட்டும் அணுகலுடன் இந்த ஒரு அனுமதியும் இருந்தால், அந்தப் பாத்திரம் தணிக்கையாளர் ஆகிறது: ஒவ்வொரு பதிவையும் படிக்கலாம், சான்றை அச்சிடலாம் அல்லது ஏற்றுமதி செய்யலாம், எதையும் மாற்ற முடியாது.',
        'evidence_saved' => 'சேமிக்கப்பட்டது',
        'checklists_heading' => 'பணிகளில் சரிபார்ப்புப் பட்டியல்கள்',
        'checklists_desc' => 'சரிபார்ப்புப் பட்டியல்கள் தொகுதியிலிருந்து ஒரு பட்டியலைப் பணியுடன் இணைத்து, செல்லும்போது அதன் படிகளை டிக் செய்ய அனுமதிக்கவும் - டிக்கெட்டுகள் பயன்படுத்தும் அதே பட்டியல்கள், நடைமுறையைப் பின்பற்றும் வேலைக்காக.',
        'checklists_enabled_name' => 'பணிகளில் சரிபார்ப்புப் பட்டியல்களை அனுமதி',
        'checklists_enabled_desc' => 'ஒவ்வொரு பணி மற்றும் துணைப் பணியிலும் சரிபார்ப்புப் பட்டியல் பகுதியைச் சேர்க்கிறது. பணிகளுக்கு அல்லது இரண்டிற்கும் பொருந்துமாறு அமைக்கப்பட்ட பட்டியல்களை மட்டுமே இணைக்க முடியும்.',
