        'procedures_enabled_name' => 'பணிகளில் நடைமுறைகள்',
        'procedures_enabled_desc' => 'ஒரு பணி அல்லது மீண்டும் நிகழும் பணி, அறிவுத்தளக் கட்டுரைகளை அதன் நடைமுறையாகக் குறிப்பிட அனுமதிக்கிறது; அவை படிக்க அனுமதி உள்ள அனைவருக்கும் பணியின் வேலை பார்வையில் காட்டப்படும். பணி முடிக்கப்படும்போது, அது எதன்படி செய்யப்பட்டதோ அந்த உரை அதனுடன் வைக்கப்படுகிறது, எனவே கட்டுரையில் பின்னர் செய்யும் திருத்தங்கள் பதிவை மாற்றி எழுதாது.',
        'forms_enabled_desc' => 'ஒரு பணி அல்லது மீண்டும் நிகழும் பணிக்கு படிவங்கள் தொகுதியிலிருந்து படிவங்கள் தேவைப்பட அனுமதிக்கிறது - அந்த நிகழ்வுக்காக நிரப்பப்பட்டு, தானாக அதனுடன் இணைக்கப்பட்டு, பணி முடிக்கப்படுவதற்கு முன் சரிபார்க்கப்படும். மீண்டும் நிகழும் பணியின் ஒவ்வொரு புதிய நிகழ்வும் பதிலளிக்கப்படாத படிவங்களுடன் தொடங்குகிறது.',
        'checklists_note' => 'நிலையான சரிபார்ப்புப் பட்டியல், கட்டாயப் படிகள் நிலுவையில் இருந்தாலும் பணியை முடிக்க அனுமதிக்கிறது, யார் செய்தார்கள் என்பதை பணியின் வரலாற்றில் பதிவு செய்கிறது. முக்கியமானது என்பது அந்தப் படிகள் முடியும் வரை பணியை முடிக்க விடாது. இதை அணைத்தால் பகுதி மறைக்கப்படும், அமல்படுத்துவதும் நிற்கும்; ஒரு சரிபார்ப்புப் பட்டியலும் நீக்கப்படாது.',
        'add' => 'சேர்',
