        'statuses_intro' => 'ஒரு பணியின் பணிப்பாய்வு நிலைகள் — கான்பன் நெடுவரிசைகளாகவும் பட்டியலை வடிகட்டவும் பயன்படுத்தப்படுகின்றன. மூடப்பட்டது எனக் குறிக்கப்பட்ட நிலைகள் முடிந்தவையாகக் கணக்கிடப்படும். புதிய பணிகளுக்கு சரியாக ஒரு நிலை இயல்புநிலை.',
