        'calendar_heading' => 'நாட்காட்டி',
        'calendar_intro' => 'தொடக்க தேதி காலக்கெடுவுக்கு முந்தைய ஒரு பல நாள் பணி, பணி நாட்காட்டியில் எவ்வாறு வரையப்படுகிறது என்பதைக் கட்டுப்படுத்துகிறது. காலக்கெடு தேதி மட்டும் உள்ள பணி, பயன்முறை எதுவாயினும் அந்தத் தேதியில் எப்போதும் ஒற்றைக் குறியாகத் தோன்றும்.',
        'span_deadline_name' => 'காலக்கெடு குறி',
        'span_deadline_desc' => 'பணி அதன் காலக்கெடு தேதியில் ஒருமுறை தோன்றும். மிகவும் நேர்த்தியான விருப்பம் — முடிக்க வேண்டியதில் நாட்காட்டியைக் கவனம் வைக்கிறது. முழுக் காலமும் காலவரிசையில் இன்னும் காணப்படும்.',
        'span_span_name' => 'தொடர் பட்டை',
        'span_span_desc' => 'பணி அதன் தொடக்க தேதியிலிருந்து காலக்கெடு வரை ஒரு தொடர் பட்டையாக, வார வரிசைகளில் பரந்து வரையப்படுகிறது. காலஅளவை ஒரே பார்வையில் காண சிறந்தது.',
        'span_repeat_name' => 'ஒவ்வொரு நாளும்',
        'span_repeat_desc' => 'பணி உள்ளடக்கும் ஒவ்வொரு நாளிலும் ஒரு குறி தோன்றும். முழுமையானது, ஆனால் நீண்ட பணிகள் கட்டத்தை நெரிசலாக்கலாம்.',
        'card_heading' => 'அட்டை',
        'card_intro' => 'பணிகளைத் திறக்காமலேயே பார்வையிட, பலகையில் ஒவ்வொரு பணி அட்டையிலும் என்ன கூடுதல் விவரங்கள் தோன்ற வேண்டும் எனத் தேர்வுசெய்க. பணித் தலைப்பு எப்போதும் காட்டப்படும். மாற்றங்கள் பலகை அடுத்த முறை ஏற்றப்படும்போது நடைமுறைக்கு வரும்.',
