        'tag_allow_create_desc' => 'பகுப்பாய்வாளர்கள் ஒரு பணியைத் திருத்தும்போது புதிய குறிச்சொல் உருவாக்க அனுமதிக்கிறது. அணைப்பு — குறிச்சொற்களை இங்கு அமைப்புகளில் மட்டுமே சேர்க்கலாம்.',
