        'modal_colour_help' => 'பணி அட்டைகள் மற்றும் கான்பன் பலகையில் பேட்ஜ்களுக்குப் பயன்படுத்தப்படுகிறது.',
        'modal_closed' => 'மூடப்பட்டதாகக் கணக்கிடு',
        'modal_closed_help' => 'இந்த நிலையில் உள்ள பணிகள் திறந்த-பணி எண்ணிக்கையாளர்களிலிருந்து விலக்கப்படும்.',
        'modal_default' => 'புதிய பணிகளுக்கு இயல்புநிலை',
        'modal_default_help' => 'ஒரே ஒரு வரிசை மட்டுமே இயல்புநிலையாக இருக்கலாம் — இதை அமைத்தால் மற்றவற்றில் இருந்து கொடி அகற்றப்படும்.',
