    'help' => [
        'page_title' => 'Service Desk - பணிகள் வழிகாட்டி',
        'guide' => 'வழிகாட்டி',
        'nav_overview' => 'மேலோட்டம்',
        'nav_board' => 'பலகை',
        'nav_list' => 'பட்டியல் காட்சி',
        'nav_calendar' => 'நாட்காட்டி காட்சி',
        'nav_timeline' => 'காலவரிசை காட்சி',
        'nav_table' => 'அட்டவணை காட்சி',
        'nav_panel' => 'பணி பலகம்',
        'nav_tags' => 'குறிச்சொற்கள்',
        'nav_evidence' => 'வரலாறும் ஆதாரமும்',
        'evidence_heading' => 'வரலாறும் ஆதாரமும்',
        'evidence_intro' => 'ஒவ்வொரு பணியும் ஒரு வரலாற்றைப் பேணுகிறது, ஒவ்வொரு மீண்டும் நிகழும் பணிக்கும் ஒரு ஆதார அறிக்கை உண்டு: &ldquo;இந்த ஆண்டு ஒவ்வொரு மாதமும் இந்தச் சரிபார்ப்பு செய்யப்பட்டதைக் காட்டுங்கள்&rdquo; என்று தணிக்கையாளர் கேட்கும்போது தேவைப்படும் பதிவு.',
        'evidence_history_heading' => 'பணியின் வரலாறு',
        'evidence_history_body' => 'பணி சாளரத்தில் உள்ள <strong>வரலாறு</strong> தாவல், பணிக்கு நடந்த அனைத்தையும் புதியது முதலாகப் பட்டியலிடுகிறது: அதை உருவாக்கியவர் (ஒரு நபர் அல்லது <em>மீண்டும் நிகழ்வு</em>), ஒவ்வொரு நிலை மாற்றமும், <strong>யார் முடித்தார்</strong> மற்றும் அப்போதைய காலக்கெடு தேதி, மீண்டும் திறத்தல், காலக்கெடு தேதி, தொடக்க தேதி மற்றும் ஒதுக்கப்பட்டவர் மாற்றங்கள், தவிர்த்தலும் அதன் காரணமும், இணைக்கப்பட்ட மற்றும் அகற்றப்பட்ட சரிபார்ப்புப் பட்டியல்கள், மற்றும் அதன் சரிபார்ப்புப் பட்டியல் படிகளில் ஒவ்வொரு டிக், டிக் நீக்கம், மதிப்பு மற்றும் முடிவு. பணி முடிந்த பிறகு செய்யப்பட்ட மாற்றங்கள் அவ்வாறே குறிப்பிடப்படும். இதில் எதையும் திருத்தவோ நீக்கவோ முடியாது; பணி நீக்கப்பட்டாலும் இது பதிவில் இருக்கும்.',
        'evidence_history_note' => 'இது உங்கள் FreeITSM-இல் சேர்க்கப்பட்ட நாளிலிருந்து வரலாறு தொடங்குகிறது. அதற்கு முந்தையவை - எடுத்துக்காட்டாக, பழைய பணியை யார் முடித்தார் என்பது - ஒருபோதும் பதிவு செய்யப்படவில்லை; அறிக்கை ஊகிக்காமல் <em>பதிவு செய்யப்படவில்லை</em> என்று கூறுகிறது.',
        'evidence_report_heading' => 'ஆதார அறிக்கை',
        'evidence_report_body' => 'மீண்டும் நிகழும் பணியிலிருந்து (<strong>மீண்டும் நிகழ்வு &rarr; செயல்படுத்தல் வரலாறு</strong>) அல்லது <strong>பணிகள் &rarr; ஆதாரம்</strong> என்பதிலிருந்து திறக்கவும்; இது நிறுத்தப்பட்டவை மற்றும் அவற்றின் பணிகள் அனைத்தும் நீக்கப்பட்டவை உட்பட மீண்டும் நிகழும் ஒவ்வொரு பணியையும் பட்டியலிடுகிறது. <em>திட்டமிடப்பட்ட</em> தேதிகளின் காலத்தைத் தேர்ந்தெடுக்கவும். நடந்திருக்க வேண்டிய ஒவ்வொரு நிகழ்வுக்கும் அதன் முடிவு, யார் முடித்தார், அதன் சரிபார்ப்புப் பட்டியல் முடிவுகள் மற்றும் விதிவிலக்குகளுடன் ஒரு வரிசை கிடைக்கும்:',
        'evidence_outcome_on_time' => '<strong>நேரத்தில்</strong> - அதன் அசல் காலக்கெடு தேதியில் (மீண்டும் நிகழ்வு அதற்கு அமைத்த தேதி) அல்லது அதற்கு முன், மற்றும் மாற்றப்பட்ட தேதியில் அல்லது அதற்கு முன் முடிக்கப்பட்டது.',
        'evidence_outcome_rescheduled' => '<strong>மறுஅட்டவணைக்குப் பின் நேரத்தில்</strong> - அதன் அசல் காலக்கெடு தேதிக்குப் பிறகு, ஆனால் அப்போது மாற்றப்பட்டிருந்த தேதியில் அல்லது அதற்கு முன் முடிக்கப்பட்டது. 1-ஆம் தேதி காலக்கெடு, 8-ஆம் தேதிக்கு மாற்றப்பட்டு, 7-ஆம் தேதி முடிக்கப்பட்டால் இதுவே - வெறும் நேரத்தில் என்று ஒருபோதும் ஆகாது.',
        'evidence_outcome_late' => '<strong>தாமதம்</strong> - அப்போது நடைமுறையில் இருந்த காலக்கெடு தேதிக்குப் பிறகு முடிக்கப்பட்டது.',
        'evidence_outcome_open' => '<strong>திறந்தவை</strong> மற்றும் <strong>காலம் கடந்தது</strong> - இன்னும் முடிக்கப்படவில்லை, காலக்கெடு தேதிக்கு முன் அல்லது பின்.',
        'evidence_outcome_skipped' => '<strong>தவிர்க்கப்பட்டது</strong> - காரணத்துடன் வேண்டுமென்றே மூடப்பட்டது.',
        'evidence_outcome_missing' => '<strong>காணவில்லை</strong> - அது இருந்திருக்க வேண்டும், ஆனால் இல்லை. நிலையான அட்டவணையில், விதி உருவாக்கிய தேதிக்கு நிகழ்வு இல்லை. முடித்த பிறகு என்றால், முந்தையது முடியும் வரை ஒருபோதும் இல்லை - ஆனால் முடிப்பு அல்லது தவிர்த்தல் அடுத்ததைத் தேவையாக்கிய பிறகு, அடுத்தது தோன்றாவிட்டால் அது காணவில்லை.',
        'evidence_outcome_removed' => '<strong>அகற்றப்பட்டது</strong> - உருவாக்கப்பட்டு, பிறகு நீக்கப்பட்டது. அதன் சரிபார்ப்புப் பட்டியல் முடிவுகள், விதிவிலக்குகள் மற்றும் வரலாறு வைக்கப்பட்டு காட்டப்படும்.',
        'evidence_flags' => 'முடிவுக்கு அருகில் கொடிகள்: <strong>மறுஅட்டவணையிடப்பட்டது</strong> (முடிப்பதற்கு முன் காலக்கெடு தேதி மாற்றப்பட்டது), <strong>முடிந்த பிறகு காலக்கெடு தேதி மாற்றப்பட்டது</strong> (இது முடிவை ஒருபோதும் மாற்றாது), <strong>தாமதமாக உருவாக்கப்பட்டது</strong> (வேலை தொடங்கியிருக்க வேண்டிய பிறகு திட்டமிடுபவர் உருவாக்கினார்) மற்றும் <strong>முடிந்த பிறகு மாற்றப்பட்டது</strong> (முடிந்த பிறகு ஒரு சரிபார்ப்புப் பட்டியல் படி மாறியது). நேரங்கள் நிறுவலின் நேர மண்டலத்தில் காட்டப்படும், மேலும் காலக்கெடு தேதி என்பது அங்குள்ள ஒரு நாட்காட்டி நாள்.',
        'evidence_why' => 'காணாத அல்லது தாமதமான நிகழ்வுக்கு, அந்த நேரத்தில் மீண்டும் நிகழும் பணிகள் வேலையின் இயக்க வரலாறு காட்டுவதை அறிக்கை சேர்க்கிறது (அறிக்கையிடல் &rarr; கணினி பதிவுகள் &rarr; பின்னணி வேலைகள் பார்க்கவும்): <em>பதிவு செய்யப்பட்ட இயக்கம் இல்லை</em>, செய்தியுடன் <em>வேலை தோல்வியடைந்தது</em>, அல்லது <em>நிரப்பு இயக்கத்தால் உருவாக்கப்பட்டது</em>. வேலை இயங்கவில்லை என்று அது ஒருபோதும் கூறாது - பதிவானதை மட்டுமே கூறும் - இயக்க வரலாறு வைக்கப்படுவதற்கு முந்தைய நேரத்துக்கு <em>கிடைக்கவில்லை</em> என்று கூறும். அறிக்கையைப் பார்ப்பதோ ஏற்றுமதி செய்வதோ ஒருபோதும் பணியை உருவாக்காது.',
        'evidence_skip_heading' => 'ஒரு நிகழ்வைத் தவிர்த்தல்',
        'evidence_skip_body' => 'மீண்டும் நிகழ்வின் ஒரு நிகழ்வு நடக்கக்கூடாது என்றால் - அது சரிபார்க்கும் சேவையகம் மாற்றப்பட்டுக்கொண்டிருந்தது என்று வைத்துக்கொள்வோம் - <strong>மீண்டும் நிகழ்வு &rarr; தவிர்</strong> என்பதைப் பயன்படுத்தி காரணத்தைக் கொடுக்கவும். அது முடிந்தது என்றல்லாமல் <em>தவிர்க்கப்பட்டது</em> என்று, அமைப்புகள் &rarr; ஆதாரம் என்பதில் தேர்ந்தெடுத்த நிலைக்கு மூடப்படும், மேலும் அறிக்கை அதை காரணத்துடன் காட்டுகிறது. முடிந்த பிறகு மீண்டும் நிகழும்படி அமைக்கப்பட்ட மீண்டும் நிகழ்வு, முடிப்பது போலவே தனது அடுத்த நிகழ்வை உருவாக்குகிறது.',
        'evidence_results_heading' => 'தேர்ச்சி, தோல்வி மற்றும் பொருந்தாது',
        'evidence_results_body' => 'ஒரு சரிபார்ப்புப் பட்டியல் படி டிக்கிற்குப் பதிலாக ஒரு <strong>முடிவு</strong> கேட்கலாம்: சரிபார்ப்புப் பட்டியல்கள் தொகுதியில், படியில் <strong>முடிவு கேள்</strong> என்பதை இயக்கவும். அப்போது பணியில் அது <strong>தேர்ச்சி</strong>, <strong>தோல்வி</strong> மற்றும் <strong>பொருந்தாது</strong> என்று காட்டும், தோல்வி என்றால் சேமிப்பதற்கு முன் என்ன தவறு நடந்தது என்று கேட்கும். தோல்வியுற்ற படியுடனும் பணியை முடிக்கலாம் - அறிக்கை அதை ஒரு <strong>விதிவிலக்கு</strong> என்று காட்டுகிறது, எனவே முடிந்த பணி தேர்ச்சி பெறாத கட்டுப்பாட்டை ஒருபோதும் மறைக்காது. இது இல்லாத படிகள் தங்கள் டிக்கை வைத்திருக்கும், டிக்கெட்டுகள் எப்போதும் டிக்கையே பயன்படுத்தும். சரிபார்ப்புப் பட்டியல் டெம்ப்ளேட்டைச் சேமிப்பது அதற்கு முந்தைய பதிப்பை வைத்திருக்கும், ஒவ்வொரு பணியும் தனக்குக் கொடுக்கப்பட்ட பதிப்பைப் பதிவு செய்கிறது.',
        'evidence_export_heading' => 'அச்சிடுதலும் ஏற்றுமதியும்',
        'evidence_export_body' => '<strong>அச்சிடு</strong> அறிக்கையை <em>அச்சிடு &rarr; PDF ஆகச் சேமி</em> என்பதற்குத் தயாராகத் திறக்கிறது. நான்கு CSV கோப்புகள் - நிகழ்வுகள், சரிபார்ப்புப் பட்டியல் முடிவுகள், இணைப்புகளும் கருத்துகளும், படிவ பதில்கள் - பணி ஐடிகளைப் பகிர்வதால் விரிதாளில் இணைக்கலாம். ஒவ்வொரு அச்சிடலும் ஏற்றுமதியும் யார், எப்போது என்பதுடன் அறிக்கையில் பதிவு செய்யப்படும்.',
        'evidence_auditor_heading' => 'தணிக்கையாளர் பங்கு',
        'evidence_auditor_body' => 'ஒருவருக்கு பணிகளுக்கான <strong>படிக்க மட்டும்</strong> அணுகலை (System &rarr; பகுப்பாய்வாளர்கள் அல்லது குழுக்கள் &rarr; தொகுதி அணுகல்) வழங்கவும், மேலும் அமைப்புகள் &rarr; ஆதாரம் அறிக்கையைக் கட்டுப்படுத்தினால், <strong>ஆதார அறிக்கையை இயக்கு</strong> என்பதைக் கொண்ட ஒரு பங்கையும் வழங்கவும். அவர்கள் தங்கள் நிறுவனங்கள் அனுமதிக்கும் ஒவ்வொரு பணியையும் திறக்கலாம், அதன் வரலாற்றைப் படிக்கலாம், ஆதாரத்தை அச்சிடலாம் அல்லது ஏற்றுமதி செய்யலாம்; எதையும் உருவாக்கவோ, மாற்றவோ, முடிக்கவோ, தவிர்க்கவோ, நீக்கவோ முடியாது. படிவங்கள் தொகுதியை வழங்காமல், அந்தப் பணிகளில் உள்ள படிவங்களின் பதில்களை அவர்கள் படிக்க அனுமதிக்க, அவர்களின் பங்குடன் <strong>நீங்கள் காணக்கூடிய பணிகளின் படிவ பதில்களைப் படி</strong> என்பதைச் சேர்க்கவும்.',
        'work_heading' => 'வேலை காட்சி',
        'work_body' => 'வேலைப் பொருட்களைக் கொண்ட பணிக்கு - சரிபார்ப்புப் பட்டியல்கள், படிவங்கள் அல்லது நடைமுறைகள் - அவற்றை ஒன்றாகக் கொண்டுவரும் <strong>வேலை</strong> பகுதி உண்டு: பணி எதற்காக, எந்த நாளுக்கானது, முன்னேற்றம் (<em>5-இல் 3 முடிந்தது</em>, சரிபார்ப்புப் பட்டியல் படிகளையும் தேவையான படிவங்களையும் எண்ணி), அறிவுறுத்தல்கள், அதன் நடைமுறைகள், சரிபார்ப்புப் பட்டியல்கள் மற்றும் படிவங்கள் - மேலும் நிலைப் பெட்டி கேட்கும் அதே கேள்விகளைக் கேட்கும் <strong>முடி</strong>. பெரிய சாளரத்தின் தாவல் அமைப்பில் இது <strong>வேலை</strong> தாவல், வேலை உள்ள பணி அங்கேயே திறக்கும் - அது வேண்டாம் என்றால் தாவலில் <em>இங்கே திற</em> என்பதைத் தேர்வுநீக்கவும்; இரு-நெடுவரிசை அமைப்பில் அகன்ற நெடுவரிசையில் இருக்கும்; பக்கப் பலகத்தில் வரிசையாக இருக்கும்.',
        'work_procedures' => '<strong>பணிகளில் நடைமுறைகள்</strong> இயக்கப்பட்டிருந்தால் (அமைப்புகள் &rarr; சரிபார்ப்புப் பட்டியல்கள்), ஒரு பணி <strong>அறிவுத்தளம் கட்டுரைகளை</strong> தன் நடைமுறையாகக் குறிப்பிடலாம், அவை இடத்திலேயே படிக்கப்படும். ஒவ்வொன்றும் அறிவுத்தளத்தின் சொந்த அணுகலைப் பின்பற்றும்: ஒரு கட்டுரையைப் படிக்க அனுமதி இல்லாதவர், நடைமுறை இருக்கிறது என்பதைக் காண்பார், அது என்ன சொல்கிறது என்பதை அல்ல. மீண்டும் நிகழும் பணியின் ஒவ்வொரு நிகழ்வும் அதே நடைமுறைகளைப் பின்பற்றும். ஒரு நிகழ்வு முடிக்கப்படும்போது, ஒவ்வொரு கட்டுரையின் உரை <em>அப்போது இருந்தவாறே</em> அதனுடன் வைக்கப்படும், எனவே கட்டுரையை பின்னர் திருத்துவது வேலை எதற்கு எதிராகச் செய்யப்பட்டது என்பதை ஒருபோதும் மாற்றாது - ஆதார அறிக்கை அந்த உரையை <strong>பயன்படுத்திய நடைமுறைகள்</strong> என்பதன் கீழ் ஒருமுறை பட்டியலிடுகிறது.',
        'work_followups' => '<strong>தொடர் நடவடிக்கைகள்</strong>: ஒரு சரிபார்ப்பு சரிசெய்ய வேண்டிய ஒன்றைக் கண்டறிந்தால், வேலை காட்சியிலிருந்து அதற்கு ஒரு <strong>பணி</strong> அல்லது <strong>டிக்கெட்</strong> உருவாக்கவும் - தோல்வியுற்ற படி அல்லது சமர்ப்பிக்கப்பட்ட படிவத்தில் <em>தொடர்</em> என்பது அது எங்கிருந்து வந்தது என்பதை நிரப்புகிறது - அல்லது ஏற்கனவே உள்ள ஒன்றை இணைக்கவும். ஒவ்வொன்றும் இன்னும் திறந்திருக்கிறதா என்பதைக் காட்டும். அமைப்புகள் &rarr; ஆதாரம் அவ்வாறு கூறாவிட்டால், சரிபார்ப்பை முடிப்பது சரிசெய்தலுக்காகக் காத்திருக்காது: இயல்பாக, சீரமைப்பு தொடரும்போதே மறுஆய்வு முடிந்ததாக இருக்கலாம். தொடர் நடவடிக்கை டிக்கெட் நீங்கள் கையால் உருவாக்கும் எந்த டிக்கெட்டையும் போலவே, உங்களால், கோரிக்கையாளராக, உருவாக்கப்படுகிறது.',
        'work_period' => '<strong>மீண்டும் நிகழும் சரிபார்ப்புகள்</strong> ஒவ்வொரு நிகழ்வும் எதை உள்ளடக்குகிறது, எப்போது காலக்கெடு என்பதைக் கூறலாம்: <em>ஒவ்வொரு நிகழ்வும் சரிபார்ப்பது</em> அதற்கான நாளை, முந்தைய நாளை (நேற்றிரவு காப்புப்பிரதிகள்) அல்லது முந்தையதிலிருந்து அனைத்தையும்; <em>ஒவ்வொரு நிகழ்வின் காலக்கெடு</em> அதே நாளில், சில நாட்கள் கழித்து, அல்லது அடுத்த வேலை நாளில். சனிக்கிழமை சரிபார்ப்பு திங்களன்று காலக்கெடுவாக இருந்து திங்களன்று முடிக்கப்பட்டால் ஆதார அறிக்கையில் அது <strong>நேரத்தில்</strong>; செவ்வாயன்று முடிக்கப்பட்டால் தாமதம். ஒரு படிவத்தில், படிவ வடிவமைப்பாளரில் ஒரு தேர்வை <strong>விதிவிலக்கு</strong> என்று டிக் செய்யலாம் - எச்சரிக்கை, தோல்வி - அதைத் தேர்ந்தெடுத்தால் ஆதார அறிக்கையில் அந்த நிகழ்வின் விதிவிலக்குகளில் பதிலைப் பட்டியலிடும்.',
        'forms_heading' => 'பணிக்குத் தேவையான படிவங்கள்',
        'forms_body' => '<strong>பணிகளில் படிவங்கள்</strong> இயக்கப்பட்டிருந்தால் (அமைப்புகள் &rarr; சரிபார்ப்புப் பட்டியல்கள்), ஒரு பணிக்கு படிவங்கள் தொகுதியிலிருந்து படிவங்கள் தேவைப்படலாம் - எடுத்துக்காட்டாக, சரி / எச்சரிக்கை / தோல்வி மற்றும் விளக்கத்துடன் ஒரு தினசரி காப்புப்பிரதி சரிபார்ப்பு. பணி சாளரத்தில் <strong>படிவங்கள்</strong> என்பதன் கீழ் ஒன்றைச் சேர்த்து <strong>தேவை</strong> (சமர்ப்பிக்கும் வரை பணியை முடிக்க முடியாது), <strong>தேவை (எச்சரிக்கை)</strong> (முடிக்கலாம், அது பதிவு செய்யப்படும்) அல்லது <strong>விருப்பத்தேர்வு</strong> என்பதைத் தேர்ந்தெடுக்கவும். மீண்டும் நிகழும் பணியில் ஒவ்வொரு புதிய நிகழ்வுக்கும் அதே படிவங்கள் பதிலளிக்கப்படாமல் தேவைப்படும் - முந்தைய பதில்கள் ஒருபோதும் தொடராது.',
        'forms_fill' => '<strong>நிரப்பு</strong> இந்த நிகழ்வுக்கான படிவத்தை, அதன் அனைத்து கேள்விகள், நிபந்தனைகள் மற்றும் சரிபார்ப்புகளுடன், வேலை காட்சியிலேயே திறக்கிறது (<em>புதிய தாவலில் திற</em> அதற்குத் தனிப் பக்கம் தரும்). <strong>வரைவைச் சேமி</strong> அதை பிறகுக்கு வைத்திருக்கும், வரைவு அந்த நிகழ்வுக்குச் சொந்தமானது, எனவே சக ஊழியர் அதைத் தொடரலாம்; கடைசியாகச் சேமித்தவரை பணி காட்டும். நீங்கள் திறந்து வைத்திருக்கும்போது வேறொருவர் சேமித்தால், எதுவும் மேலெழுதப்படாது: யார், எப்போது என்று உங்களுக்குத் தெரிவிக்கப்படும், உங்கள் பதில்கள் திரையில் இருக்கும், அவர்களுடையதைப் பயன்படுத்துவதா உங்களுடையதை வைத்திருப்பதா என்று நீங்கள் தேர்வு செய்வீர்கள். <strong>சமர்ப்பி</strong> பதில்களை இந்த நிகழ்வுடன் இணைக்கிறது - நகலெடுக்க குறிப்பு எண்கள் இல்லை - <strong>திருத்து</strong> பின்னர் அவற்றை மாற்றுகிறது, முந்தைய சமர்ப்பிப்பைப் பதிவில் வைத்திருக்கிறது.',
        'forms_complete' => 'பணியை முடிப்பது அதன் தேவையான படிவங்களை சரிபார்ப்புப் பட்டியல் படிகளைச் சரிபார்ப்பது போலவே சரிபார்க்கிறது, எவ்வாறு முடிக்கப்பட்டாலும் - நிலைப் பெட்டி, அட்டையை இழுத்தல், துணைப் பணியை டிக் செய்தல் அல்லது API. முடிப்பது என்பது சரிபார்ப்பு செய்யப்பட்டு பதிவு செய்யப்பட்டது என்று பொருள்: எச்சரிக்கை அல்லது தோல்வி பதில் ஆதார அறிக்கையில் அவ்வாறே இருக்கும்; அறிக்கை ஒவ்வொரு நிகழ்வின் படிவங்களையும் பதில்களையும் பட்டியலிடுகிறது, மேலும் ஒரு <strong>படிவ பதில்கள் CSV</strong> உள்ளது.',
        'forms_access' => 'பணியில் படிவத்தை நிரப்ப, படிவங்கள் பக்கத்தில் உள்ளது போலவே, படிவங்களுக்கான அணுகல் தேவை. பதில்களைப் படிக்க படிவங்களுக்கான அணுகல் <em>அல்லது</em> <strong>நீங்கள் காணக்கூடிய பணிகளின் படிவ பதில்களைப் படி</strong> என்ற பங்கு அனுமதி தேவை - பணியைக் காண முடிவது மட்டும் போதாது. இரண்டும் இல்லாவிட்டால், படிவம் சமர்ப்பிக்கப்பட்டது, யாரால், எப்போது என்பதைக் காண்பீர்கள், ஆனால் பதில்களை அல்ல - பணி சாளரம், ஆதார அறிக்கை மற்றும் அதன் CSV ஆகிய அனைத்திலும்.',
        'forms_note' => 'பணிக்காகச் செய்யப்பட்ட சமர்ப்பிப்பு அந்த நிகழ்வின் பதிவு, எனவே படிவங்கள் தொகுதியிலிருந்து அதை நீக்க முடியாது, அத்தகைய சமர்ப்பிப்புகள் உள்ள படிவத்தையும் நீக்க முடியாது - அதற்குப் பதிலாக செயலற்றதாக்கவும். பல-நிறுவன நிறுவலில் அந்தப் பணியைக் காணக்கூடியவர்களுக்கு மட்டுமே இது காட்டப்படும்.',
        'nav_settings' => 'அமைப்புகள்',
        'nav_tips' => 'விரைவு குறிப்புகள்',
        'nav_companies' => 'நிறுவனங்கள்',
        'companies_heading' => 'பணிகளும் நிறுவனங்களும்',
        'companies_intro' => 'ஒரு பணி எந்த வாடிக்கையாளருக்குச் சொந்தம், தவறான நிறுவனத்தின் கீழ் பதிவான பணியை எப்படி நகர்த்துவது.',
        'companies_scope' => 'ஒவ்வொரு பணியும் சரியாக ஒரு நிறுவனத்திற்குச் சொந்தம். டிக்கெட்டிலிருந்து உருவாக்கப்பட்ட பணி அந்த டிக்கெட்டின் நிறுவனத்தை எடுத்துக்கொள்ளும்; நீங்களே உருவாக்கும் பணி நீங்கள் தற்போது பணிபுரியும் நிறுவனத்தை எடுத்துக்கொள்ளும். உங்களுக்கு அணுகல் வழங்கப்பட்ட நிறுவனங்களின் பணிகளை மட்டுமே நீங்கள் காண்பீர்கள்.',
        'companies_move' => 'தவறான வாடிக்கையாளரின் கீழ் பதிவாகிவிட்டதா? பணியை வலது கிளிக் செய்து <strong>நிறுவனத்திற்கு நகர்த்து</strong> என்பதைத் தேர்ந்தெடுக்கவும் — பலகை, அட்டவணை அல்லது காலவரிசையில். நீங்களே அணுகக்கூடிய நிறுவனத்திற்கு மட்டுமே பணியை நகர்த்த முடியும், மேலும் நகர்த்தல் பணியின் வரலாற்றில் பதிவு செய்யப்படும், எனவே எது, எப்போது நகர்ந்தது என்பதற்குப் பதிவு உண்டு.',
        'companies_subtasks' => 'துணைப் பணிகள் தங்கள் பெற்றோருடன் ஒரே நேரத்தில் நகரும். துணைப் பணியைத் தனியாக நகர்த்த முடியாது, ஏனெனில் அது எப்போதும் மேலுள்ள பணியின் அதே நிறுவனத்திற்குச் சொந்தமானது — அவற்றைப் பிரித்தால் உங்கள் ஊழியர்களில் சிலரால் பார்க்க முடியாத குழந்தையுடன் ஒரு பெற்றோர் மிஞ்சும்.',
        'companies_links' => 'டிக்கெட் அல்லது மாற்றத்துடன் இணைக்கப்பட்ட பணி அதை விட்டு நகராது; எந்த இணைப்பு தடையாக உள்ளது என்று உங்களுக்குத் தெரிவிக்கப்படும், எனவே இணைப்பை அகற்றலாம் அல்லது மற்ற பதிவையும் நகர்த்தலாம். ஒப்பந்தத்துடனான இணைப்பு நகர்த்தலை ஒருபோதும் தடுக்காது, ஏனெனில் ஒப்பந்தங்கள் ஒரே நிறுவனத்தின் கீழ் பதிவு செய்யப்படுவதில்லை.',
        'hero_title' => 'பணிகள் தொகுதி வழிகாட்டி',
        'hero_subtitle' => 'உள் வேலையை Kanban பலகையில் திட்டமிடவும், ஒதுக்கவும், கண்காணிக்கவும் &mdash; நாட்காட்டி, காலவரிசை, குறிச்சொற்கள் மற்றும் நிலை வாரி நெடுவரிசைகளுடன்.',
        'overview_heading' => 'மேலோட்டம்',
        'overview_intro' => 'பணிகள் தொகுதி உங்கள் சர்வீஸ் டெஸ்க் குழுவுக்கான இலகுவான வேலை கண்காணிப்பான். டிக்கெட்டுகள் அல்லாத வேலைகளுக்குப் பயன்படுத்தவும் &mdash; திட்ட வேலை, உள் நிர்வாகம், தொடர் வேலைகள், தொடர் நடவடிக்கைகள் &mdash; அவற்றை Kanban பலகையாக, வரிசைப்படுத்தக்கூடிய பட்டியலாக, நாட்காட்டியாக, Gantt பாணி காலவரிசையாக அல்லது முழுத்திரை திருத்தக்கூடிய விரிதாளாகக் காணலாம். பணிகளை டிக்கெட்டுகள் மற்றும் மாற்றங்களுடன் இணைக்கலாம், குறிச்சொற்களைக் கொண்டிருக்கலாம், துணைப் பணிகளாகப் பிரிக்கலாம்.',
        'overview_card1_title' => 'பலகை',
        'overview_card1_desc' => 'ஒவ்வொரு நிலைக்கும் ஒரு நெடுவரிசை கொண்ட Kanban பலகை. நிலையை மாற்ற அட்டைகளை நெடுவரிசைகளுக்கு இடையே இழுக்கவும், மறுவரிசைப்படுத்த நெடுவரிசைத் தலைப்புகளை இழுக்கவும், நெடுவரிசையிலேயே பணிகளை விரைவாகச் சேர்க்கவும்.',
        'overview_card2_title' => 'பட்டியல் காட்சி',
        'overview_card2_desc' => 'அதே பணிகள் வரிசைப்படுத்தக்கூடிய அட்டவணையாக &mdash; தலைப்பு, நிலை, முன்னுரிமை, ஒதுக்கப்பட்டவர், குழு அல்லது காலக்கெடு தேதியின்படி வரிசைப்படுத்த எந்த நெடுவரிசைத் தலைப்பையும் கிளிக் செய்யவும்.',
        'overview_card3_title' => 'நாட்காட்டி',
        'overview_card3_desc' => 'பணிகளை காலக்கெடு தேதியின்படி வைக்கும் மாதக் கட்டம். பல நாள் பணிகள் ஒற்றைச் சிப்பாக, பரவும் பட்டையாக அல்லது ஒவ்வொரு நாளிலும் ஒரு சிப்பாகக் காட்டப்படலாம் &mdash; தேர்வு உங்களுடையது, அமைப்புகளில்.',
        'overview_card4_title' => 'காலவரிசை',
        'overview_card4_desc' => 'ஒவ்வொரு பணியையும் அதன் தொடக்க தேதியிலிருந்து காலக்கெடு தேதி வரையிலான பட்டையாகக் காட்டும் Gantt பாணி வரைபடம். மறுஅட்டவணையிட பட்டைகளை இழுக்கவும், தொடக்க மற்றும் காலக்கெடு தேதிகளை அமைக்க விளிம்புகளை இழுக்கவும்.',
        'overview_card5_title' => 'அட்டவணை',
        'overview_card5_desc' => 'கலத்திலேயே திருத்தும் வசதியுடன் Excel பாணி கட்டம் &mdash; நிலை, முன்னுரிமை, ஒதுக்கப்பட்டவர், குழு அல்லது தேதிகளை வரிசையிலேயே மாற்றவும். நெடுவரிசைகள், வரிசை, வடிகட்டி மற்றும் தேடல் ஒவ்வொரு பகுப்பாய்வாளருக்கும் நினைவில் இருக்கும்.',
        'overview_card6_title' => 'குறிச்சொற்கள்',
        'overview_card6_desc' => 'குறுக்குத் தலைப்புகளுக்கான பல-மதிப்பு லேபிள்கள் &mdash; பாதுகாப்பு, ISO, சூழல் &mdash; அவற்றின் மூலம் வடிகட்டவும் தேடவும் முடியும்.',
        'overview_card7_title' => 'அமைப்புகள்',
        'overview_card7_desc' => 'நிலைகள், முன்னுரிமைகள் மற்றும் குறிச்சொற்களை உள்ளமைக்கவும்; நாட்காட்டியின் பல நாள் காட்சியையும் ஒவ்வொரு அட்டையும் காட்டுவதையும் கட்டுப்படுத்தவும்.',
        'overview_tip' => 'பலகை, பட்டியல், நாட்காட்டி மற்றும் காலவரிசை ஆகியவை ஒரே பணிகளின் மீதான வெவ்வேறு சாளரங்கள் மட்டுமே. ஒன்றில் செய்த மாற்றம் அனைத்திலும் பிரதிபலிக்கும்.',
        'board_heading' => 'பலகை',
        'board_intro' => 'பலகை இயல்புநிலை காட்சி &mdash; ஒவ்வொரு நிலைக்கும் ஒரு நெடுவரிசை கொண்ட Kanban அமைப்பு. எல்லாம் எங்கே இருக்கிறது என்பதைப் பார்க்கவும் வேலையை முன்னெடுக்கவும் இது வேகமான வழி.',
        'board_columns_heading' => 'நெடுவரிசைகள் என்பவை நிலைகள்',
        'board_columns_body' => 'ஒவ்வொரு நெடுவரிசையும் அமைப்புகள் &rarr; நிலைகள் என்பதில் வரையறுக்கப்பட்ட ஒரு நிலை, காட்சி வரிசையில், நிலையின் நிறம் தலைப்புப் புள்ளியாக காட்டப்படும். ஒரு நிலையைச் சேர்த்தால் அது நெடுவரிசை ஆகிறது; நிர்வகிக்க தனி "நெடுவரிசை" கருத்து இல்லை. நெடுவரிசைகளை மறுவரிசைப்படுத்த, <strong>நெடுவரிசைத் தலைப்பை</strong> இடது அல்லது வலது பக்கம் இழுக்கவும் &mdash; புதிய வரிசை சேமிக்கப்படும்.',
        'board_creating_heading' => 'பணிகளை உருவாக்குதல்',
        'board_creating_step1' => '<strong>நெடுவரிசைத் தலைப்பில் + ஐ கிளிக் செய்யவும்</strong> &mdash; அந்த நெடுவரிசையின் மேல் ஒரு உள்வரிசைப் பெட்டி திறக்கும்.',
        'board_creating_step2' => '<strong>தலைப்பை உள்ளிட்டு Enter அழுத்தவும்</strong> &mdash; அந்த நெடுவரிசையின் நிலையில் பணி உருவாக்கப்பட்டு உங்களுக்கு ஒதுக்கப்படும். மீதியை நிரப்ப எப்போது வேண்டுமானாலும் அதைக் கிளிக் செய்யவும்.',
        'board_moving_heading' => 'நகர்த்துதலும் மறுவரிசைப்படுத்தலும்',
        'board_moving_body' => 'நிலையை மாற்ற அட்டையை வேறு நெடுவரிசைக்கு இழுக்கவும்; மறுவரிசைப்படுத்த நெடுவரிசைக்குள் மேலும் கீழும் இழுக்கவும். அது எங்கே இறங்கும் என்பதை ஒரு ஊதா கோடு காட்டும். அட்டையை <em>மூடப்பட்டது</em> எனக் குறிக்கப்பட்ட நிலையில் விட்டால் அதன் முடிவு நேரம் தானாகப் பதிவாகும்.',
        'board_rightclick_heading' => 'அட்டையை வலது கிளிக் செய்யவும்',
        'board_rightclick_body' => 'எந்த அட்டையையும் வலது கிளிக் செய்தால் விரைவுச் செயல் பட்டி திறக்கும் &mdash; அட்டையையே திறக்காமல் பகுப்பாய்வாளர் அல்லது குழுவை ஒதுக்கலாம், நிலை அல்லது முன்னுரிமையை மாற்றலாம், துணைப் பணியை உருவாக்கலாம்.',
        'board_search_heading' => 'தேடலும் வடிப்பான்களும்',
        'board_search_body' => 'பக்கப்பட்டியில் ஒரு <strong>தேடு</strong> பெட்டி (நீங்கள் தட்டச்சு செய்யும்போதே வடிகட்டும், தலைப்பு மற்றும் விளக்கத்தையும் &mdash; இயக்கப்பட்டிருந்தால் குறிச்சொல் பெயர்களையும் பொருத்தும்) மற்றும் <strong>என் பணிகள் / அனைத்து பணிகள்</strong>, <strong>குழு</strong>, <strong>பகுப்பாய்வாளர்</strong>, இயக்கப்பட்டிருந்தால் <strong>குறிச்சொல்</strong> ஆகியவற்றுக்கான வடிப்பான்களும் உள்ளன. வடிப்பான்களும் தேடலும் பட்டியல் காட்சிக்கும் பொருந்தும். மூடப்பட்ட நிலையில் உள்ள ஒவ்வொரு பணியையும் தவிர்க்க <strong>முடிந்தவற்றை மறை</strong> என்பதை டிக் செய்யவும் - பலகையில் அது முடிந்த நெடுவரிசைகளையும் மறைக்கும். இது உங்களுக்காக நினைவில் வைக்கப்படும், முடிந்த பணி ஒருபோதும் <em>காலம் கடந்தது</em> எனக் காட்டப்படாது.',
        'board_subtasks' => 'பணியின் துணைப் பணிகள் அதன் அட்டையின் கீழ் பட்டியலிடப்படும் - ஒன்றைத் திறக்க கிளிக் செய்யவும். பணிக்குள், வரிசையை மாற்ற துணைப் பணியை அதன் <strong>&#8942;&#8942;</strong> கைப்பிடியால் இழுக்கவும். அட்டைகள் எந்த துணைப் பணிகளைப் பட்டியலிடும் என்பதை பக்கப்பட்டியில் <strong>அட்டைகளில் துணைப் பணிகள்</strong> என்பதன் கீழ் தேர்ந்தெடுக்கவும்: <strong>அனைத்தும்</strong>, <strong>திறந்தவை</strong> (இன்னும் செய்ய வேண்டியவை மட்டும்) அல்லது <strong>எதுவுமில்லை</strong> (எண்ணிக்கை மட்டும்). அமைப்பு என்ன சொன்னாலும், அந்த ஒரு அட்டையின் துணைப் பணிகளைக் காட்ட அல்லது மறைக்க அட்டையின் எண்ணிக்கையை, எ.கா. <strong>1/4</strong>, கிளிக் செய்யவும். இரண்டும் உங்களுக்காக நினைவில் வைக்கப்படும்.',
        'board_card_order' => 'ஒவ்வொரு நெடுவரிசைக்குள்ளும் அட்டைகள் எப்படி அமரும் என்பதைத் தேர்ந்தெடுக்க இடது பலகத்தில் <strong>அட்டை வரிசை</strong> என்பதைப் பயன்படுத்தவும். <strong>கைமுறை</strong> என்பது அட்டைகள் இழுக்கப்பட்ட வரிசை, அது அனைவருக்கும் பொதுவானது. <strong>காலக்கெடு தேதி</strong> காலம் கடந்த வேலையை முதலிலும், பிறகு இன்று காலக்கெடு உள்ளதையும், மீதியை தேதிப்படியும் வைக்கும்; காலக்கெடு தேதி இல்லாத பணிகள் கீழே இருக்கும் - உங்களுக்கு மட்டும், கைமுறை வரிசையை மாற்றாமல், திரும்ப மாறும்போது அது முன்பு இருந்தவாறே வரும். காலக்கெடு தேதியின்படி வரிசைப்படுத்தியிருக்கும்போதும் அட்டையை வேறு நெடுவரிசைக்கு இழுக்கலாம்; நெடுவரிசைக்குள் அட்டைகளை மறுசீரமைக்க கைமுறைக்கு மாறவும். உங்கள் தேர்வு நினைவில் வைக்கப்படும்.',
        'board_columns_by_analyst' => 'அதற்குப் பதிலாக ஒவ்வொரு நபருக்கும் ஒரு நெடுவரிசையைக் காண, இடது பலகத்தில் <strong>நெடுவரிசைகள் &rarr; பகுப்பாய்வாளர்</strong> என்பதைப் பயன்படுத்தவும் (முதலில் உங்களுடையது, பிறகு <em>ஒதுக்கப்படவில்லை</em>), ஒவ்வொரு அட்டையும் அதன் நிலையைக் காட்டும். அட்டையை வேறொருவரின் நெடுவரிசைக்கு இழுத்தால் பணி அவருக்கு ஒதுக்கப்படும். உங்கள் தேர்வு நினைவில் வைக்கப்படும்.',
        'board_tip' => 'ஒவ்வொரு அட்டையும் காட்டுவதைத் தேர்ந்தெடுக்கவும் &mdash; முன்னுரிமை, ஒதுக்கப்பட்டவர், குழு, தேதிகள், விளக்கச் சுருக்கம், துணைப் பணி முன்னேற்றம், குறிச்சொற்கள் &mdash; அமைப்புகள் &rarr; அட்டை என்பதன் கீழ், அதனால் பணிகளைத் திறக்காமலே பார்வையிடலாம்.',
        'list_heading' => 'பட்டியல் காட்சி',
        'list_intro' => 'பட்டியல் பலகையின் தரவு இரட்டை &mdash; அதே பணிகள் வரிசைப்படுத்தக்கூடிய அட்டவணையாக. பக்கப்பட்டியில் உள்ள காட்சி மாற்றியால் இதற்கு மாறவும்.',
        'list_body' => 'எந்த நெடுவரிசைத் தலைப்பையும் &mdash; தலைப்பு, நிலை, முன்னுரிமை, ஒதுக்கப்பட்டவர், குழு, காலக்கெடு &mdash; கிளிக் செய்தால் அதன்படி வரிசைப்படுத்தப்படும்; திசையைத் திருப்ப மீண்டும் கிளிக் செய்யவும். தேடலும் பக்கப்பட்டி வடிப்பான்களும் பலகையில் உள்ளதுபோலவே செயல்படும், எனவே பட்டியலைச் சுருக்கி, மீதியை வரிசைப்படுத்தலாம். பணியைத் திறக்க ஒரு வரிசையைக் கிளிக் செய்யவும்.',
        'list_tip' => 'பலகை நெடுவரிசை இல்லாத நிலையுள்ள பணியை (எடுத்துக்காட்டாக தனிப்பயன் "Icebox" நிலை) கண்டறிய பட்டியலே இடம் &mdash; நிலை எதுவாக இருந்தாலும் பட்டியல் ஒவ்வொரு பணியையும் காட்டும்.',
        'calendar_heading' => 'நாட்காட்டி காட்சி',
        'calendar_intro' => 'காலக்கெடுக்களையும் பணிச்சுமையையும் ஒரே பார்வையில் காண நாட்காட்டி பணிகளை தேதிக் கட்டத்தில் வைக்கிறது. பணிகள் அவற்றின் நிலையின்படி வண்ணமிடப்படும்.',
        'calendar_body' => 'கருவிப்பட்டியில் <strong>இன்று</strong>, முந்தையது / அடுத்தது, மற்றும் வலதுபுறம் <strong>மாதம் / வாரம் / நாள்</strong> காட்சி மாற்றி உள்ளன. <em>மாதம்</em> என்பது பழக்கமான 4&ndash;6 வார கட்டம்; <em>வாரம்</em> திரையை நிரப்பும் ஏழு நாள் வரிசையைப் பெரிதாக்குகிறது; <em>நாள்</em> ஒரு தேதிக்கு வந்து, அன்று நிகழும் ஒவ்வொரு பணியையும் அட்டை வரிசையாகப் பட்டியலிடுகிறது. முந்தையது / அடுத்தது பொத்தான்கள் செயலில் உள்ள காட்சிக்கு ஏற்ப மாதம், வாரம் அல்லது நாள் வாரியாக நகரும்.',
        'calendar_sidebar' => 'பக்கப்பட்டியில் நிற விளக்கம், பலகையில் உள்ளதே போன்ற என்னுடையவை / அனைத்தும் / குழு / பகுப்பாய்வாளர் வடிப்பான்கள், மற்றும் நாட்காட்டி அமைப்புகளுக்கு நேரடியாகச் செல்லும் மாற்று இணைப்புடன் கூடிய <strong>கால அளவு பயன்முறை</strong> பலகம் ஆகியவை உள்ளன.',
        'calendar_click_heading' => 'ஒரு பணியைக் கிளிக் செய்தல்',
        'calendar_click_body' => 'ஒரு பணிச் சிப், பார் அல்லது நாள் காட்சி வரிசையைக் கிளிக் செய்தால், நாட்காட்டியின் வலதுபுறம் ஒரு ஸ்லைடு-இன் <strong>விரைவு பலகம்</strong> திறக்கும் &mdash; நீங்கள் இருக்கும் இடத்திலேயே இருப்பீர்கள். தலைப்பு, நிலை, முன்னுரிமை, ஒதுக்கப்பட்டவர், குழு மற்றும் தேதிகள் அனைத்தையும் பலகத்திலேயே திருத்தலாம்; rich-text விளக்கம், துணைப் பணிகள் அல்லது கருத்துகள் தேவைப்படும்போது, மேலே உள்ள தொடக்க ஐகான் டாஷ்போர்டின் முழு எடிட்டரைத் திறக்கும்.',
        'calendar_multiday_heading' => 'பல நாள் பணிகள் எவ்வாறு வரையப்படுகின்றன',
        'calendar_multiday_body' => 'தொடக்க தேதி காலக்கெடு தேதிக்கு முன்பு உள்ள ஒரு பணி பல நாட்களை உள்ளடக்கும். அந்த வரம்பு எவ்வாறு காட்டப்படும் என்பது அமைப்புகள் &rarr; நாட்காட்டியில் ஒவ்வொரு நிறுவலுக்கும் ஒருமுறை அமைக்கப்படுகிறது:',
        'calendar_field_deadline' => '<strong>காலக்கெடு சிப்</strong> &mdash; காலக்கெடு தேதியில் மட்டும் ஒரு சிப். மிக நேர்த்தியான விருப்பம்; முழு கால அளவையும் காலவரிசையில் இன்னும் காணலாம்.',
        'calendar_field_span' => '<strong>பரவும் பார்</strong> &mdash; முழு வரம்பு முழுவதும் ஒரே தொடர் பார், வார வரிசைகளில் சுற்றிச் செல்லும். கால அளவைப் பார்க்க சிறந்தது.',
        'calendar_field_everyday' => '<strong>ஒவ்வொரு நாளும்</strong> &mdash; பணி உள்ளடக்கும் ஒவ்வொரு நாள் கட்டத்திலும் ஒரு சிப். முழுமையானது, ஆனால் நீண்ட பணிகள் கட்டத்தை நெரிசலாக்கலாம்.',
        'calendar_note' => 'காலக்கெடு தேதி மட்டுமே உள்ள பணி, எந்தப் பயன்முறை தேர்ந்தெடுக்கப்பட்டிருந்தாலும் அந்த தேதியில் எப்போதும் ஒரே சிப்பாகக் காட்டப்படும்.',
        'timeline_heading' => 'காலவரிசை காட்சி',
        'timeline_intro' => 'காலவரிசை என்பது Gantt பாணி வரைபடம். ஒவ்வொரு பணியும் அதன் தொடக்க தேதியிலிருந்து காலக்கெடு தேதி வரை செல்லும் கிடைமட்ட பார் ஆகும்; இதனால் மேற்பொருந்தல்கள், இடைவெளிகள் மற்றும் கால அளவுகளைப் பார்க்கலாம்.',
        'timeline_body' => 'காலக்கெடு தேதி மட்டுமே உள்ள பணி ஒரு நாள் பாராகக் காட்டப்படும். வரிசைகளை <strong>ஒதுக்கப்பட்டவர்</strong>, <strong>நிலை</strong> வாரியாகக் குழுவாக்கலாம் அல்லது தட்டையாகக் காட்டலாம் &mdash; பக்கப்பட்டியிலிருந்து தேர்ந்தெடுக்கவும். புள்ளிக்கோடு குறியீடு இன்றைக் காட்டுகிறது, ஸ்க்ரோல் செய்யும்போது பணிப் பெயர் நெடுவரிசையும் தேதி தலைப்பும் இடத்திலேயே இருக்கும், நாள் கட்டம் திரைக்குத் தானாகப் பொருந்தும்: குறுகிய வரம்புகள் ஓரத்திலிருந்து ஓரம் வரை விரியும், நீண்டவை ஒவ்வொரு நாளையும் வசதியான அளவில் வைத்து கிடைமட்டமாக ஸ்க்ரோல் ஆகும்.',
        'timeline_drag_heading' => 'மறுதிட்டமிட பார்களை இழுக்கவும்',
        'timeline_drag_body' => 'பார்கள் நேரடி எடிட்டர்கள். ஒன்றின் மீது கர்சரை வைத்தால் இரு முனைகளிலும் ஒளிபுகும் பிடிகள் தோன்றும்:',
        'timeline_field_body' => '<strong>பாரின் நடுப்பகுதியை இழுக்கவும்</strong> &mdash; தொடக்க மற்றும் காலக்கெடு தேதிகள் இரண்டும் ஒரே நாட்கள் எண்ணிக்கையில் நகரும். கால அளவு மாறாமல் பணி முழுமையாக நகரும்.',
        'timeline_field_left' => '<strong>இடது விளிம்பை இழுக்கவும்</strong> &mdash; தொடக்க தேதி மட்டும் மாறும். காலக்கெடு அப்படியே இருக்க, தொடக்கத்தை முன்கூட்டியோ தாமதமாகவோ மாற்ற பயனுள்ளது.',
        'timeline_field_right' => '<strong>வலது விளிம்பை இழுக்கவும்</strong> &mdash; காலக்கெடு தேதி மட்டும் மாறும். காலக்கெடு மட்டுமே உள்ள பணியில் (தொடக்க தேதி அமைக்கப்படாதது), பழைய காலக்கெடு தேதி புதிய தொடக்க தேதியாகிறது; இதனால் பார் புதிய முடிவில் ஒரு நாள் நிலைக்குத் தாவாமல், முறையான வரம்பாக வளரும்.',
        'timeline_snap_note' => 'இழுத்தல்கள் முழு நாட்களுக்குப் பொருந்தும். ஒரு பாரின் மீது குறுகிய, இழுக்காத கிளிக் இன்னும் பணியைத் திறக்கும் &mdash; 3px நகர்வு வரம்புக்குக் கீழே அது இழுத்தலாக அல்லாமல் கிளிக்காகக் கருதப்படும்.',
        'timeline_rightclick_heading' => 'விரைவு செயல்களுக்கு ரைட்-கிளிக்',
        'timeline_rightclick_body' => 'பலகை பயன்படுத்தும் அதே சூழல் மெனுவுக்கு எந்த பாரையும் ரைட்-கிளிக் செய்யவும் &mdash; <strong>பகுப்பாய்வாளரை ஒதுக்கு</strong>, <strong>குழுவை ஒதுக்கு</strong>, <strong>நிலையை மாற்று</strong>, <strong>முன்னுரிமையை மாற்று</strong> &mdash; எதையும் திறக்காமலே. ஒவ்வொரு துணை மெனுவும் பணியின் தற்போதைய மதிப்பை டிக் குறியுடன் காட்டும்.',
        'timeline_click_heading' => 'ஒரு பாரைக் கிளிக் செய்தல்',
        'timeline_click_body' => 'ஒரு பாரில் (அல்லது இடதுபுறம் உள்ள பணிப் பெயர் நெடுவரிசையில்) சாதாரண கிளிக் செய்தால், நாட்காட்டி பயன்படுத்தும் அதே ஸ்லைடு-இன் விரைவு பலகம் காலவரிசையின் வலதுபுறம் திறக்கும். அன்றாடப் புலங்களை அங்கேயே திருத்தலாம், அல்லது பலகத்தின் மேலே உள்ள தொடக்க ஐகானை அழுத்தி டாஷ்போர்டின் முழு எடிட்டருக்குச் செல்லலாம்.',
        'table_heading' => 'அட்டவணை காட்சி',
        'table_intro' => 'அட்டவணை காட்சி என்பது முழுத்திரை Excel பாணி கட்டம் &mdash; ஒரு பணிக்கு ஒரு வரிசை, திருத்தக்கூடிய கலங்களுடன். பட்டியலை வகைப்படுத்த, புலங்களை மொத்தமாகச் சரிசெய்ய அல்லது நீங்கள் வேலை செய்ய விரும்பும் நெடுவரிசை அமைப்பை உருவாக்க இதுவே வேகமான இடம்.',
        'table_edit_heading' => 'கலத்திலேயே திருத்தவும்',
        'table_edit_body' => 'பெரும்பாலான நெடுவரிசைகள் நிலையான உரைக்குப் பதிலாக திருத்தக்கூடிய கட்டுப்பாட்டைக் காட்டுகின்றன. கீழ்விரியிலிருந்து புதிய நிலை அல்லது முன்னுரிமையைத் தேர்ந்தெடுங்கள், ஒதுக்கப்பட்டவரை அல்லது குழுவை மாற்றுங்கள், புதிய தலைப்பை உள்ளிடுங்கள், புதிய தொடக்க / காலக்கெடு தேதியை உள்ளிடுங்கள் அல்லது தேர்ந்தெடுங்கள் &mdash; ஒவ்வொரு கலமும் மாற்றும்போதே சேமிக்கப்படும், தேட வேண்டிய சேமி பொத்தான் இல்லை. நிலை மற்றும் முன்னுரிமை நிறப் புள்ளியைக் காட்டும்; சேமித்த பிறகு அது அதே இடத்தில் புதுப்பிக்கப்படும்.',
        'table_views_heading' => 'சேமித்த காட்சிகள்',
        'table_views_body' => 'அட்டவணை நீங்கள் விரும்பும் வகையில் அமைந்ததும் &mdash; சரியான நெடுவரிசைகள், வரிசைப்படுத்தல், வடிகட்டல் &mdash; கருவிப்பட்டியில் உள்ள <strong>காட்சியைச் சேமி</strong> அந்த அமைப்பை ஒரு பெயரில் வைத்திருக்கும், அதன் அருகில் உள்ள <strong>காட்சிகள்</strong> நூலகத்தைத் திறக்கும். ஒரு காட்சி <strong>உங்களுக்கு மட்டும்</strong>, <strong>உங்கள் குழுக்களில் ஒன்றுக்கு</strong> அல்லது <strong>அனைவருக்கும்</strong> தெரியலாம்; நட்சத்திரம் ஒன்றை உங்கள் இயல்புநிலையாக்கும், அதனால் அட்டவணை அதனுடன் திறக்கும். நூலகத்தைப் பெயர், விளக்கம் அல்லது உருவாக்கியவர் மூலம் தேடலாம், பட்டியலாகவோ அட்டைகளாகவோ காட்டலாம்.',
        'table_views_note' => 'நெடுவரிசைகள், வரிசைப்படுத்தல் மற்றும் வடிப்பான்கள் சேமிக்கப்படுகின்றன; தேடல் பெட்டி வேண்டுமென்றே சேமிக்கப்படுவதில்லை, ஏனெனில் தேடல் என்பது நீங்கள் ஒருமுறை கேட்ட கேள்வி, விஷயங்களைப் பார்க்க நீங்கள் விரும்பும் முறை அல்ல. சொத்துகள், நாட்காட்டி மற்றும் மாற்ற மேலாண்மை அட்டவணைகளிலும் இதே காட்சிகள் உள்ளன, ஒவ்வொன்றும் தனக்கானதை வைத்திருக்கும்.',
        'table_columns_heading' => 'நெடுவரிசைகள்: காட்டு, மறை, மறுவரிசைப்படுத்து',
        'table_columns_body' => 'அட்டவணை அறிந்த ஒவ்வொரு நெடுவரிசையுடன் ஒரு டிராயரைத் திறக்க கருவிப்பட்டியில் உள்ள <strong>நெடுவரிசைகள்</strong> பொத்தானைக் கிளிக் செய்யவும். தெரிய வேண்டியவற்றைத் தேர்வுசெய்யவும்; மறுவரிசைப்படுத்த வரிசைகளை இழுக்கவும். நெடுவரிசை தலைப்பில் உள்ள இழுப்பு கைப்பிடியும் நெடுவரிசைகளை நேரடியாக மறுவரிசைப்படுத்தும். உங்கள் தெரிவுநிலையும் வரிசையும் உங்கள் கணக்கில் சேமிக்கப்படும், அடுத்த முறை அட்டவணையைத் திறக்கும்போது நீங்கள் விட்டுச் சென்றபடியே இருக்கும்.',
        'table_sort_heading' => 'வரிசைப்படுத்து, வடிகட்டு, தேடு',
        'table_field_sort' => '<strong>வரிசைப்படுத்து</strong> &mdash; எந்த நெடுவரிசை தலைப்பையும் கிளிக் செய்து அதன்படி வரிசைப்படுத்தலாம். திசையை மாற்ற மீண்டும் கிளிக் செய்யவும். செயலில் உள்ள வரிசைப்படுத்தல் நெடுவரிசை அமைப்புடன் சேர்ந்து ஒவ்வொரு பகுப்பாய்வாளருக்கும் சேமிக்கப்படும்.',
        'table_field_filter' => '<strong>வடிகட்டு</strong> &mdash; அந்த நெடுவரிசை உண்மையில் கொண்டுள்ள ஒவ்வொரு மதிப்பின் Excel பாணி தேர்வுப்பெட்டி பட்டியலைத் திறக்க, நெடுவரிசை தலைப்பில் உள்ள புனல் ஐகானைக் கிளிக் செய்யவும். வேண்டாதவற்றின் தேர்வை நீக்குங்கள்; பட்டியலில் உள்ள எண்ணிக்கைகள் ஒவ்வொரு மதிப்புக்கும் எத்தனை வரிசைகள் பொருந்துகின்றன என்பதைக் காட்டும். செயலில் உள்ள வடிப்பான்கள் புனலை ஊதா நிறத்தில் காட்டும்.',
        'table_field_search' => '<strong>தேடு</strong> &mdash; கருவிப்பட்டியின் தேடல் பெட்டி தெரியும் ஒவ்வொரு நெடுவரிசையின் உரையையும் பொருத்தும். நீங்கள் தட்டச்சு செய்யும்போதே வடிகட்டும்.',
        'table_field_reset' => '<strong>மீட்டமை</strong> &mdash; கருவிப்பட்டியின் மீட்டமை பொத்தான் அனைத்து வடிப்பான்களையும் தேடல் பெட்டியையும் அழித்து, வரிசைப்படுத்தலை மீட்டமைக்கும்.',
        'table_export_heading' => 'ரைட்-கிளிக் மற்றும் ஏற்றுமதி',
        'table_export_body' => 'ஒரு வரிசையை ரைட்-கிளிக் செய்தால் பலகையும் காலவரிசையும் பயன்படுத்தும் அதே சூழல் மெனு திறக்கும் &mdash; பகுப்பாய்வாளர் / குழுவை ஒதுக்கு, நிலை / முன்னுரிமையை மாற்று. கருவிப்பட்டியில் உள்ள <strong>CSV</strong> பொத்தான் தற்போதைய காட்சியை (தெரியும் நெடுவரிசைகள், தேடல், வடிப்பான்கள் மற்றும் வரிசைப்படுத்தலை மதித்து) Excel சரியாகத் திறக்கும் UTF-8 CSV ஆகப் பதிவிறக்கும்.',
        'table_tip' => 'நீங்கள் ஒரு கலத்தைத் திருத்திக்கொண்டிருக்கும்போது வரிசைப்படுத்தலும் வடிகட்டலும் மீண்டும் <em>இயங்காது</em> &mdash; அவை உங்கள் கவனத்தைப் பறிக்கும். உங்கள் திருத்தம் உடனே சேமிக்கப்படும்; அடுத்த முறை வரிசைப்படுத்தலையோ வடிப்பானையோ மாற்றும்போது அல்லது மீட்டமை அழுத்தும்போது, புதிய மதிப்பே பயன்படுத்தப்படும்.',
        'panel_heading' => 'பணிப் பலகம்',
        'panel_intro' => 'ஒரு பணியைக் கிளிக் செய்தால் வலதுபுறம் ஸ்லைடு-இன் பலகம் திறக்கும். ஒவ்வொரு புலமும் மாற்றும் கணமே தானாகச் சேமிக்கப்படும் &mdash; சேமி பொத்தான் இல்லை. பலகையின் பலகம் முழு எடிட்டர்; நாட்காட்டியும் காலவரிசையும் அன்றாடப் புலங்களுடன் கூடிய இலகுவான <em>விரைவு பலகத்தைத்</em> திறக்கின்றன, rich-text விளக்கம், துணைப் பணிகள் அல்லது கருத்துகள் தேவைப்படும்போது முழு எடிட்டருக்குச் செல்ல தொடக்க ஐகான் உள்ளது.',
        'panel_field_title' => '<strong>தலைப்பு</strong> &mdash; பலகத்தின் மேலே கிளிக் செய்து தட்டச்சு செய்யவும்.',
        'panel_field_status' => '<strong>நிலை &amp; முன்னுரிமை</strong> &mdash; நீங்கள் உள்ளமைத்த பட்டியல்களிலிருந்து உருவாக்கப்பட்ட கீழ்விரிகள்.',
        'panel_field_assignee' => '<strong>ஒதுக்கப்பட்டவர் &amp; குழு</strong> &mdash; பணிக்கு யார் உரிமையாளர், அது எந்தக் குழுவைச் சேர்ந்தது.',
        'panel_field_contractor' => '<strong>ஒப்பந்ததாரர் &amp; அங்குள்ள தொடர்பு</strong> &mdash; வெளி நிறுவனம் வேலை செய்யும்போது: ஒப்பந்தங்களிலிருந்து ஒரு வழங்குநர், விரும்பினால் அங்குள்ள ஒருவர். அவர்களைத் தொடர்புகொள்ளும் இங்குள்ள நபராக ஒதுக்கப்பட்டவர் இருப்பார். ஒன்றைத் தேர்ந்தெடுக்க ஒப்பந்தங்களுக்கான அணுகல் தேவை.',
        'panel_contractor_note' => '<strong>ஒப்பந்ததாரர் பணி</strong> அட்டையில் ‘நிறுவனத்தின் பெயர்&rsquo; காட்டப்படும்; இடது பலகத்தில் உள்ள <strong>ஒப்பந்ததாரர்</strong> வடிப்பான் (எந்தப் பணிக்காவது ஒன்று இருந்தால் காட்டப்படும்) பலகையை ஒரு நிறுவனத்துக்கு, ஒப்பந்ததாரர் உள்ள ஒவ்வொரு பணிக்கு, அல்லது எதுவுமில்லாதவற்றுக்குக் குறைக்கும். நிறுவனத்தில் உள்ள நபருக்குப் பணி வழங்கப்படும்போதும் அது காலக்கெடுவை அடையும்போதும் திட்டங்கள் அவருக்கு மின்னஞ்சல் அனுப்பலாம் &mdash; திட்டங்கள் &rarr; அமைப்புகளில் யாராவது இயக்காவிட்டால் அணைந்தே இருக்கும்.',
        'panel_field_dates' => '<strong>தொடக்க &amp; காலக்கெடு தேதிகள்</strong> &mdash; இவை சேர்ந்து நாட்காட்டியிலும் காலவரிசையிலும் காட்டப்படும் கால அளவை வரையறுக்கின்றன.',
        'panel_field_tags' => '<strong>குறிச்சொற்கள்</strong> &mdash; தட்டச்சு செய்து வடிகட்டும் தேர்வி; விரும்பிய அளவு சேர்க்கலாம், ஒவ்வொரு சிப்பிலும் உள்ள &times; மூலம் அகற்றலாம்.',
        'panel_field_desc' => '<strong>விளக்கம்</strong> &mdash; தடித்த எழுத்து, பட்டியல்கள் மற்றும் இணைப்புகளுடன் கூடிய rich-text எடிட்டர்.',
        'panel_field_links' => '<strong>இணைப்புகள்</strong> &mdash; தொடர்புடைய டிக்கெட்டுகள் அல்லது மாற்றங்களைத் தேடி இணைக்கவும்.',
        'panel_links_note' => '<strong>ஒரு டிக்கெட்டும் ஒரு மாற்றமும்.</strong> ஒரு பணியை ஒரே ஒரு டிக்கெட்டுடனும் ஒரே ஒரு மாற்றத்துடனும் இணைக்கலாம்; அதனால் ஏதாவது இணைக்கப்பட்ட பிறகும் தேடல் பெட்டிகள் தெரியும், மேலும் ஒன்றை <em>அதற்குப் பதிலாக</em> இணைக்கும் வசதியைத் தரும். வேறு பதிவைத் தேர்ந்தெடுத்தால் முதலில் கேட்கும், எது இணைப்பு நீக்கப்படும் என்பதையும் குறிப்பிடும் &mdash; உங்கள் ஒப்புதல் இல்லாமல் எதுவும் மாற்றப்படாது. டிக்கெட் பக்கத்திலும் இதே எச்சரிக்கை தோன்றும்: ஏற்கனவே வேறு டிக்கெட்டுக்குச் சொந்தமான பணியை இணைத்தால் அது <em>நகர்த்தப்படும்</em>, செய்வதற்கு முன் அதைச் சொல்லும்.',
        'panel_preview_note' => '<strong>இணைக்கப்பட்ட பதிவின் அருகில் உள்ள &#9432;</strong> பணியை விட்டு வெளியேறாமல் முக்கிய விவரங்களைக் காட்டும் அட்டையைத் திறக்கும் &mdash; டிக்கெட்டின் ‘நிலை&rsquo;, முன்னுரிமை, அது யாரிடம் உள்ளது, யார் உருவாக்கினார்; மாற்றத்தின் ‘நிலை&rsquo;, அபாயம் மற்றும் திட்டமிட்ட சாளரம். இது வேண்டுமென்றே படிக்க-மட்டும், அதனால் ஒரு பார்வை தற்செயலான திருத்தமாக மாறாது. <strong>Escape</strong> அதை மூடும், <strong>திற</strong> பதிவுக்கே உங்களை அழைத்துச் செல்லும். பதிவைக் காட்ட முடியாது என்று சொன்னால், அது உங்களுக்கு அணுகல் இல்லாத பதிவு அல்லது நீக்கப்பட்டது &mdash; இரண்டுக்கும் ஒரே பதில் வேண்டுமென்றே தரப்படுகிறது.',
        'panel_field_subtasks' => '<strong>துணைப் பணிகள்</strong> &mdash; பணியை சிறிய வேலைத் துண்டுகளாகப் பிரிக்கவும், ஒவ்வொன்றுக்கும் தனி உரிமையாளர். ஒவ்வொரு வரிசையும் யாரிடம் உள்ளது என்பதையும் அதன் <strong>தொடக்க</strong> மற்றும் <strong>காலக்கெடு</strong> தேதிகளையும் காட்டும், அவற்றை அங்கேயே மாற்றலாம்; வரிசையை மாற்ற ஒரு வரிசையை அதன் <strong>&#8942;&#8942;</strong> கைப்பிடியால் இழுக்கவும். முன்னேற்றம் பெற்றோர் அட்டையில் காட்டப்படும், துணைப் பணிகள் அதன் கீழே பட்டியலிடப்படும்.',
        'panel_field_comments' => '<strong>கருத்துகள்</strong> &mdash; பணியில் தொடரும் விவாத இழை.',
        'panel_field_work' => '<strong>பணி தொடக்கம் &amp; முடிவு</strong> &mdash; பணியில் வேலை செய்யத் <em>திட்டமிடப்பட்ட</em> நேரம், <strong>நாள் முழுவதும்</strong> விருப்பத்துடன். இவை அனைவருக்கும் ஒரே மாதிரி தெரியும்: பராமரிப்பு சாளரம் போல, மாலை 2 மணி இடைவெளி யார் பார்த்தாலும் மாலை 2 மணிதான்.',
        'panel_field_time' => '<strong>நேரம்</strong> &mdash; வேலை உண்மையில் எவ்வளவு நேரம் எடுத்தது, ஒவ்வொன்றிலும் குறிப்புடன் தனித் தனி அமர்வுகளாகப் பதிவு செய்யப்பட்டு, கூட்டப்படும். பெற்றோர் பணி <em>அதன் துணைப் பணிகள் உட்பட</em> மொத்தத்தையும் காட்டும். பதிவு செய்த நேரம் ஒரு உண்மையான கணம், அதனால் உங்கள் சொந்த நேர மண்டலத்தில் தோன்றும்.',
        'panel_view_note' => 'பணி பலகையின் பக்கத்தில் ஒரு பலகத்தில் திறக்கும். அதன் மூலையில் உள்ள <strong>விரிவாக்கு</strong> பொத்தானைப் பயன்படுத்தினால், அதே உள்ளடக்கத்தை இரு நெடுவரிசைகளில் காட்டும் பெரிய சாளரம் கிடைக்கும் &mdash; விளக்கமும் கருத்துகளும் இடதுபுறம், குறுகிய புலங்கள் வலதுபுறம். பெரிய சாளரத்தில் இரண்டாவது பொத்தான் அதற்குப் பதிலாக <strong>தாவல்களுக்கு</strong> மாற்றும்: விவரங்கள், துணைப் பணிகள், நேரம், கருத்துகள், இணைப்புகள் மற்றும் ஆவணங்கள், ஒவ்வொன்றும் எத்தனை உருப்படிகள் உள்ளன என்பதைக் காட்டும். நீங்கள் எதை விரும்புகிறீர்கள் என்பதை FreeITSM நினைவில் வைக்கும், <em>விருப்பத்தேர்வுகள் &rarr; பணியைத் திறத்தல்</em> என்பதிலும் அமைக்கலாம்.',
        'panel_context_note' => 'பணியைத் திறக்காமலே இதில் பெரும்பாலானவற்றைச் செய்ய <strong>எந்த அட்டையையும் ரைட்-கிளிக் செய்யவும்</strong>: அதைத் திறக்கலாம், உங்களுக்கோ வேறு யாருக்கோ ஒதுக்கலாம், நிலை அல்லது முன்னுரிமையை மாற்றலாம், காலக்கெடு தேதி அமைக்கலாம், முடிந்ததாகக் குறிக்கலாம், நேரத்தைப் பதிவு செய்யலாம், துணைப் பணி சேர்க்கலாம், அதற்கான இணைப்பை நகலெடுக்கலாம் அல்லது நீக்கலாம்.',
        'panel_delete_note' => 'நீக்கு பொத்தான் (பலகத்தின் மேல்-வலது) பணியையும் அதன் அனைத்து துணைப் பணிகளையும் நீக்கும் &mdash; முதலில் உறுதிப்படுத்தல் கேட்கும்.',
        'nav_repeats' => 'மீண்டும் நிகழும் பணிகள்',
        'repeats_heading' => 'மீண்டும் நிகழும் பணிகள்',
        'repeats_intro' => 'சில வேலைகள் திரும்பத் திரும்ப வரும்: மாதாந்திர காப்புப்பிரதி சரிபார்ப்பு, காலாண்டு அணுகல் மதிப்பாய்வு, வாராந்திர அறிக்கை. எந்தப் பணிக்கும் ஒரு மீள்நிகழ்வை அமைக்கலாம்; நீங்கள் நினைவில் வைக்கும் தேவையின்றி FreeITSM அடுத்த நிகழ்வை உங்களுக்காக உருவாக்கும்.',
        'repeats_cron_warning' => '<strong>நிலையான அட்டவணைக்கு சர்வரில் ஒரு திட்டமிட்ட வேலை தேவை, அது இல்லாவிட்டால் எதுவும் உங்களை எச்சரிக்காது.</strong> <em>நிலையான அட்டவணையில்</em> அமைக்கப்பட்ட மீள்நிகழ்வுகள் <code>cron/task_recurrence.php</code> மூலம் உருவாக்கப்படுகின்றன. புதிய நிறுவலில் திட்டமிட்ட பணிகள் எதுவுமே இல்லை, எனவே யாராவது இதை அமைக்கும் வரை நிலையான அட்டவணை எதையும் உருவாக்காது &mdash; பிழை இல்லை, பதிவு இல்லை, அமைதியாக எதுவும் செய்யாத ஒரு மீள்நிகழ்வு மட்டுமே. இதை <strong>தினமும் ஒருமுறை</strong> இயக்கவும். இது இயங்குகிறதா என்பதை <strong>அறிக்கையிடல் &rarr; கணினி பதிவுகள் &rarr; பின்னணி வேலைகள்</strong> காட்டும். <em>இது முடிந்த பிறகு</em> என அமைக்கப்பட்ட மீள்நிகழ்வுகள் பாதிக்கப்படாது: முந்தையதை முடிக்கும் கோரிக்கைக்குள்ளேயே அவை உருவாக்கப்படுகின்றன, அதனால் திட்டமிட்ட பணிகளே இல்லாத நிறுவலிலும் அவை வேலை செய்யும்.',
        'repeats_setup_heading' => 'ஒன்றை அமைத்தல்',
        'repeats_setup_body' => 'ஒரு பணியைத் திறந்து பலகத்தில் <strong>மீள்நிகழ்வுகள்</strong> என்பதைக் கண்டறிந்து, <strong>மீள்நிகழ்வை அமை</strong> என்பதைக் கிளிக் செய்யவும். பலகையில் ஒரு அட்டையை ரைட்-கிளிக் செய்து, அதைத் திறக்காமலேயே <strong>மீள்நிகழ்வை அமை</strong> என்பதைத் தேர்ந்தெடுக்கவும் முடியும். துணைப் பணி தானாக மீளாது &mdash; மீள்நிகழ்வு வேலைக்குச் சொந்தமானது, அதற்குள் இருக்கும் ஒரு படிக்கு அல்ல.',
        'repeats_mode_heading' => 'மீள்வதற்கு இரண்டு வழிகள், வேறுபாடு முக்கியம்',
        'repeats_mode_body' => 'இது எடிட்டரில் முதல் தேர்வு, சிந்திக்கத் தகுந்தது, ஏனெனில் வேலை தாமதமாகும்போது இரண்டும் வெவ்வேறு விதமாக நடந்துகொள்ளும்.',
        'repeats_mode_completion' => '<strong>இது முடிந்த பிறகு</strong> &mdash; நீங்கள் தற்போதையதை முடிக்கும்போது அடுத்த நிகழ்வு தோன்றும், அதன் தேதி நீங்கள் உண்மையில் முடித்த நாளிலிருந்து எண்ணப்படும். பெரும்பாலானோர் &ldquo;மாதாந்திர சரிபார்ப்பு&rdquo; என்பதற்கு இதையே பொருள் கொள்கிறார்கள்: பிப்ரவரி‘யது&rsquo; 5-ஆம் தேதி முடிந்தால், மார்ச்‘சுடையது&rsquo; 5-க்குப் பிறகு ஒரு மாதத்தில் வரும். தற்போதையது திறந்திருக்கும் வரை எதுவும் உருவாக்கப்படாது, அதனால் ஒரே வேலை இரண்டு காத்திருக்காது.',
        'repeats_mode_schedule' => '<strong>நிலையான அட்டவணையில்</strong> &mdash; முந்தையது முடிந்ததா இல்லையா என்பதைப் பொருட்படுத்தாமல் நிகழ்வுகள் அவற்றின் தேதிகளில் வரும். இணக்க மதிப்பாய்வுக்கு இதுவே தேவை: ‘பிப்ரவரி&rsquo; வேலை ஒருபோதும் செய்யப்படாவிட்டாலும் மார்ச் தணிக்கை மார்ச்சில்தான் வர வேண்டும். தவறிய நிகழ்வுகள் அமைதியாகத் தவிர்க்கப்படாமல் சேரும், சர்வர் ஒரு வாரம் அணைந்திருந்தாலும் அவை இழக்கப்படாமல் வேலை பிடித்துக்கொள்ளும்.',
        'repeats_pattern_heading' => 'எவ்வளவு அடிக்கடி',
        'repeats_pattern_body' => 'ஒரு முறை என்பது ஒரு அதிர்வெண்ணும் இடைவெளியும் &mdash; ஒவ்வொரு N நாட்கள், வாரங்கள், மாதங்கள் அல்லது ஆண்டுகள் &mdash; கூடவே வாராந்திர மற்றும் மாதாந்திர மீள்நிகழ்வுகளுக்கு எந்த நாட்கள் என்ற தேர்வும்.',
        'repeats_pattern_daily' => '<strong>தினசரி</strong> &mdash; ஒவ்வொரு நாளும், அல்லது ஒவ்வொரு N நாட்களும்.',
        'repeats_pattern_weekly' => '<strong>வாராந்திர</strong> &mdash; ஒவ்வொரு வாரமும் அல்லது ஒவ்வொரு N வாரங்களும், வார நாட்களின் எந்தக் கலவையிலும். &ldquo;ஒவ்வொரு இரண்டாவது வாரமும் திங்கள் மற்றும் வியாழன்&rdquo; என்பது இரண்டு அல்ல, ஒரே விதி.',
        'repeats_pattern_dom' => '<strong>மாதாந்திர, நாள் எண் மூலம்</strong> &mdash; 1-ஆம், 15-ஆம், 28-ஆம் தேதி. மாதத்தின் நீளம் எதுவாக இருந்தாலும் கடைசி நாளுக்கு <strong>-1</strong> உள்ளிடவும்; மாத இறுதி வேலைக்கு இது தேவை, எண்ணாக எழுத முடியாது. குறுகிய மாதத்தை விட நீண்ட நாள் எண் &mdash; பிப்ரவரியில் 31-ஆம் தேதி &mdash; அந்த மாதத்தைத் தவிர்க்காமல் ‘கடைசி நாளுக்கு&rsquo; மாறும்.',
        'repeats_pattern_nth' => '<strong>மாதாந்திர, பெயரிட்ட வார நாள் மூலம்</strong> &mdash; முதல் திங்கள், மூன்றாவது புதன், கடைசி வெள்ளி. இடத்தையும் வார நாளையும் தேர்ந்தெடுக்கவும். நான்கு மட்டுமே உள்ள மாதத்தில் ஒரு வார நாளின் ஐந்தாவதைக் கேட்டால் கடைசியதற்கு மாறும், அதனால் மாதம் ஒருபோதும் தவிர்க்கப்படாது.',
        'repeats_pattern_yearly' => '<strong>ஆண்டுதோறும்</strong> &mdash; ஒவ்வொரு ஆண்டும் அல்லது ஒவ்வொரு N ஆண்டுகளும், விருப்பமாக தேர்ந்தெடுத்த மாதத்தில், மாதாந்திரத்தில் உள்ள அதே நாள் எண் அல்லது பெயரிட்ட வார நாள் தேர்வுடன்.',
        'repeats_ends_heading' => 'எப்போது நிற்கும்',
        'repeats_ends_never' => '<strong>ஒருபோதும் இல்லை</strong> &mdash; நீங்கள் நிறுத்தும் வரை தொடரும்.',
        'repeats_ends_date' => '<strong>ஒரு தேதியில்</strong> &mdash; அந்த தேதியில் அல்லது அதற்கு முன் வரும் நிகழ்வே கடைசி நிகழ்வு.',
        'repeats_ends_count' => '<strong>குறிப்பிட்ட எண்ணிக்கை நிகழ்வுகளுக்குப் பிறகு</strong> &mdash; மீள்நிகழ்வை நீங்கள் அமைத்த பணியையும் எண்ணிக்கை <em>உள்ளடக்கும்</em>. ஐந்து எனக் கேட்டால், உங்கள் முன் உள்ள பணியும் மேலும் நான்கும் கிடைக்கும்.',
        'repeats_carry_heading' => 'எவை தொடர்ந்து வரும்',
        'repeats_carry_body' => 'விளக்கம், துணைப் பணிகள், ஒதுக்கப்பட்டவர், குறிச்சொற்கள், டிக்கெட்டுகள் மற்றும் மாற்றங்களுக்கான இணைப்புகள், இணைக்கப்பட்ட ஆவணங்கள் ஒவ்வொன்றும் தனித்தனியாகத் தேர்ந்தெடுக்கப்படுகின்றன, ஏனெனில் வேலைக்கு வேலை சரியான பதில் மாறும். ஒவ்வொரு மாதமும் ஒரே படிவங்களைப் பயன்படுத்தும் சரிபார்ப்புப் பட்டியலுக்கு இணைப்புகளைக் கொண்டுவருவது சரி, ஒவ்வொரு முறையும் புதிய சான்றுகளைச் சேகரிக்க வேண்டிய தணிக்கைக்கு தவறு.',
        'repeats_carry_note' => 'புதிய நிகழ்வு எப்போதும் திறந்த, முடிக்கப்படாத நிலையில் வரும், முந்தையது மூடப்பட்ட நிலையில் அல்ல. தொடக்க தேதிக்கும் காலக்கெடு தேதிக்கும் இடையிலான இடைவெளியையும் அது வைத்திருக்கும், அதனால் இரண்டு வார வேலை இரண்டு வாரமாகவே இருக்கும்.',
        'repeats_when_heading' => 'அடுத்தது எப்போது தோன்றும்',
        'repeats_when_body' => 'ஒரு நிகழ்வு காலக்கெடு வரும்போது அல்ல, அதில் வேலை <strong>தொடங்க</strong> முடியும்போது உருவாக்கப்படும். தொடக்க தேதி காலக்கெடுவுக்கு இரண்டு வாரம் முன்பு உள்ள பணி இரண்டு வாரம் முன்பே தோன்றும்; காலக்கெடு மட்டுமே உள்ள பணி அந்த நாளில் தோன்றும். &ldquo;அறிவிப்பு நாட்கள்&rdquo; அமைப்பு வேண்டுமென்றே இல்லை: முன்னறிவிப்பு நேரம் என்பது நீங்கள் ஏற்கனவே பணிக்குக் கொடுத்த கால அளவு, பாதிக்குத் தவறாகும் ஒரு எண்ணை விட இது சிறந்த பதில்.',
        'repeats_when_note' => 'இதனால்தான் பலகையில் நீங்கள் இப்போது உண்மையில் செய்யக்கூடிய வேலை மட்டுமே இருக்கும். நிலையான அட்டவணையின் எதிர்கால நிகழ்வுகள் <strong>நாட்காட்டியில்</strong> இன்னும் தெரியும், அவற்றின் பின்னால் இன்னும் பணி இல்லாமல் மங்கலாக வரையப்படும்; அதனால் யாரும் தொடங்க முடியாத வேலைகளால் பலகை நிரம்பாமல் திட்டத்தைப் பார்க்கலாம்.',
        'repeats_preview_heading' => 'முன்னோட்டம்',
        'repeats_preview_body' => '&ldquo;மாதத்தின் ஒவ்வொரு இரண்டாவது செவ்வாய், ஐந்து முறை&rdquo; என்பதை பெரும்பாலானோர் மனதிலேயே தேதிகளாக மாற்ற முடியாது. சேமி பொத்தானின் அருகில் உள்ள <strong>முன்னோட்டம்</strong>, தற்போதைய அமைப்புகள் உருவாக்கும் ஒவ்வொரு நிகழ்வையும் அதன் தொடக்க மற்றும் காலக்கெடு தேதிகளுடன் பட்டியலிடும் &mdash; நீங்கள் சேமிக்காத அமைப்புகளும் உட்பட, அதனால் ஒரு விதியை வைத்துக்கொள்ளும் முன் சோதிக்கலாம். நீங்கள் இருக்கும் பணி முதல் நிகழ்வாகக் காட்டப்படும், ஏற்கனவே உள்ளவை குறிக்கப்படும்; அதனால் நிறுவப்பட்ட மீள்நிகழ்வை முன்னோட்டமிட்டால் அது இதுவரை செய்ததையும் இனி செய்யப்போவதையும் காட்டும். முடிவு இல்லாத மீள்நிகழ்வு முதல் 25-ஐக் காட்டும்.',
        'repeats_preview_note' => 'அமைப்புகள் எதையுமே உருவாக்காவிட்டால், முன்னோட்டம் அதைத் தெளிவாகச் சொல்லும் &mdash; பொதுவாக முடிவு அல்லது நீங்கள் தேர்ந்தெடுத்த நாள் நீங்கள் எண்ணியது அல்ல என்பதற்கான அறிகுறி. முடிந்த பிறகு இயங்க அமைக்கப்பட்ட மீள்நிகழ்வுக்குப் பட்டியலிட தேதிகள் இல்லை, ஏனெனில் அதன் அடுத்த தேதி வேலை உண்மையில் முடிந்த நாளிலிருந்து எண்ணப்படும்; முன்னோட்டம் ஊகிக்காமல் அதை விளக்கும்.',
        'repeats_finding_heading' => 'ஒரு தொடரில் வழி கண்டறிதல்',
        'repeats_finding_body' => 'ஒரு தொடரைச் சேர்ந்த பணி, பலகையிலும் நாட்காட்டியிலும் சிறிய தொடர் ஐகானைக் கொண்டிருக்கும்; பலகத்தில் தொடரில் அதன் இடத்தையும் காட்டும் &mdash; <em>12-ல் 3-வது நிகழ்வு</em>. தொடர் எந்தப் பணியிலிருந்து தொடங்கியதோ அதற்கான இணைப்பும் பலகத்தில் இருக்கும்; எனவே எந்த நிகழ்விலிருந்தும் மூலப் பணி ஒரு கிளிக் தூரத்தில் உள்ளது.',
        'repeats_stop_heading' => 'தொடரை நிறுத்துதல்',
        'repeats_stop_body' => '<strong>Stop repeating</strong> தொடரை முடிக்கும்; எதையும் நீக்காது. ஏற்கனவே உருவாக்கப்பட்ட நிகழ்வுகள் உண்மையான வேலை, அவற்றில் சில முடிந்தவை; எனவே தொடரை அணைப்பது &ldquo;இனி இவை வேண்டாம்&rdquo; என்று பொருள்படுமே தவிர &ldquo;கடந்த ஆறு மாதங்கள் நடக்கவே இல்லை என்று நடிப்பது&rdquo; அல்ல. அமைப்புகளை மாற்றி மீண்டும் சேமித்தால் எதிர்கால நிகழ்வுகளுக்கான விதி மாற்றப்படும்; ஏற்கனவே உள்ளவை தொடப்படாது.',
        'repeats_tip' => 'எந்த முறை வேண்டும் என்று உறுதியாகத் தெரியவில்லையா? தாமதமானால் அடுத்தது பின்னோக்கித் தள்ளப்பட வேண்டுமெனில் <em>இது முடிக்கப்பட்ட பிறகு</em> என்பதைத் தேர்ந்தெடுக்கவும். தாமதமானால் இரண்டு பணிகள் செய்ய வேண்டிய நிலை வந்தாலும் பரவாயில்லை எனில் <em>நிலையான அட்டவணையில்</em> என்பதைத் தேர்ந்தெடுக்கவும்.',
        'tags_heading' => 'குறிச்சொற்கள்',
        'tags_intro' => 'குறிச்சொற்கள் என்பவை பல மதிப்புகள் கொண்ட லேபிள்கள், பல பணிகளைக் கடந்த கருப்பொருள்களுக்கானவை &mdash; நிலை அல்லது முன்னுரிமைக்குள் அடங்காதவை. ஒரு பணி எத்தனை குறிச்சொற்களை வேண்டுமானாலும் கொண்டிருக்கலாம்.',
        'tags_body1' => 'நிலை "இது எந்தக் கட்டத்தில் உள்ளது?" என்பதற்கும், முன்னுரிமை "எவ்வளவு அவசரம்?" என்பதற்கும் பதில் தருகின்றன; குறிச்சொல் "இது எதைப் <em>பற்றியது</em>?" என்பதற்குப் பதில் தருகிறது &mdash; Security, ISO, Environment என்பன போல. ஒரு பணி பல குறிச்சொற்களைக் கொண்டிருக்க முடிவதால், ஒவ்வொரு நிலை மற்றும் உரிமையாளரையும் கடந்து கருப்பொருள் வாரியாக உங்கள் வேலையைப் பிரித்துப் பார்க்கலாம்.',
        'tags_body2' => 'குறிச்சொற்கள் அமைப்புகள் &rarr; குறிச்சொற்கள் என்பதில் நிர்வகிக்கப்படுகின்றன; ஒவ்வொன்றுக்கும் பெயரும் நிறமும் உண்டு. அங்குள்ள ஐந்து காட்சி விருப்பங்கள், பணியிலிருந்தே குறிச்சொற்களை உருவாக்கலாமா என்பதையும், அவை எங்கே தோன்றும் என்பதையும் கட்டுப்படுத்துகின்றன &mdash; அட்டை சிப்புகள், பக்கப்பட்டி வடிகட்டி, தேடல் பொருத்தம், நாட்காட்டி/காலவரிசை.',
        'tags_tip' => '"என்றாவது / ஒருவேளை" வகை கருப்பொருளுக்கு குறிச்சொல்தான் சரியான இடம். சில யோசனைகளை <em>Blue Sky</em> எனக் குறிச்சொல் இட்டால், தனி நெடுவரிசை இல்லாமலே குறிச்சொல் வடிகட்டி மூலம் எப்போது வேண்டுமானாலும் அவற்றை எடுக்கலாம்.',
        'settings_heading' => 'அமைப்புகள்',
        'settings_intro' => 'அமைப்புகள் பக்கத்தில் ஒவ்வொரு பகுதிக்கும் ஒரு தாவல் உண்டு; உங்கள் பங்கு மாற்ற அனுமதிக்கும் தாவல்களை மட்டுமே காண்பீர்கள். அமைப்புகள் முழு நிறுவலுக்கும் பொருந்தும்: இங்கு செய்யும் மாற்றம் உங்களுக்கு மட்டுமல்ல, முழுக் குழுவுக்கான பலகை, நாட்காட்டி மற்றும் அட்டைகளை வடிவமைக்கும்.',
        'settings_lookups_heading' => 'நிலைகள் &amp; முன்னுரிமைகள்',
        'settings_lookups_body' => 'இந்த இரண்டு தாவல்களும் ஒவ்வொரு பணியும் பயன்படுத்தும் தேடல் பட்டியல்களை நிர்வகிக்கின்றன. ஒவ்வொரு வரிசைக்கும் பெயர், நிறம், காட்சி வரிசை உண்டு; வலப்பக்கத்தில் உள்ள பொத்தான்களால் வரிசைகளைச் சேர்க்கலாம், திருத்தலாம், நீக்கலாம்.',
        'settings_field_statuses' => '<strong>நிலைகள்</strong> &mdash; பணிப்பாய்வின் நிலைகள்; இவையே பலகையின் நெடுவரிசைகளாகவும் (காட்சி வரிசைப்படி) அமைகின்றன. ஒரு நிலை புதிய பணிகளுக்கான <em>இயல்புநிலை</em>. <em>மூடப்பட்டது</em> எனக் குறிக்கப்பட்ட நிலை முடிந்ததாகக் கணக்கிடப்படும் &mdash; அதற்கு நகர்த்தப்படும் பணிகள் முடிவு நேரத்தைப் பதிவு செய்து, திறந்த பணி எண்ணிக்கைகளிலிருந்து விலகும். வரலாற்றை இழக்காமல் ஒரு நிலையை ஓய்வு பெறச் செய்ய, அதைச் செயலற்றதாகவும் ஆக்கலாம்.',
        'settings_field_priorities' => '<strong>முன்னுரிமைகள்</strong> &mdash; ஒவ்வொரு அட்டையிலும் நிறப் புள்ளியாகக் காட்டப்படும் முன்னுரிமைப் பிரிவுகள். ஒரு முன்னுரிமை புதிய பணிகளுக்கான இயல்புநிலை.',
        'settings_card_heading' => 'அட்டை',
        'settings_card_body' => 'அட்டை தாவல் என்பது தேர்வுப்பெட்டிகளின் தொகுப்பு; பணிகளைத் திறக்காமலே பார்வையிட, ஒவ்வொரு பலகை மற்றும் பட்டியல் அட்டையிலும் எந்த கூடுதல் விவரங்கள் தோன்றும் என்பதை இது கட்டுப்படுத்துகிறது: முன்னுரிமைப் புள்ளி, ஒதுக்கப்பட்டவரின் முதலெழுத்துகள், குழு, தொடக்க தேதி, காலக்கெடு தேதி, விளக்கப் பகுதி, துணைப் பணி முன்னேற்றம் மற்றும் இணைக்கப்பட்ட உருப்படி குறிகாட்டி. பணியின் தலைப்பு எப்போதும் காட்டப்படும். மாற்றங்கள் அடுத்த முறை பலகை ஏற்றப்படும்போது அமலுக்கு வரும்.',
        'settings_calendar_heading' => 'நாட்காட்டி விருப்பங்கள்',
        'settings_calendar_body' => 'நாட்காட்டி தாவலில் ஒரே ஒரு முடிவுதான் உள்ளது: <strong>பல நாள் பணி</strong> &mdash; தொடக்க தேதி காலக்கெடு தேதிக்கு முந்தையதாக உள்ள பணி &mdash; பணிகள் நாட்காட்டியில் எவ்வாறு வரையப்படுகிறது என்பது. மூன்று முறைகளில் ஒன்றைத் தேர்ந்தெடுக்கவும்:',
        'settings_calendar_deadline' => '<strong>காலக்கெடு சிப்</strong> (இயல்புநிலை) &mdash; பணி அதன் காலக்கெடு தேதியில் ஒரே ஒரு சிப்பாக ஒருமுறை தோன்றும். இது நாட்காட்டியை கால அளவுகளில் அல்லாமல் முடிக்க வேண்டியவற்றில் கவனம் செலுத்த வைக்கிறது; நிறைய பணிகள் இருக்கும்போது இதுவே சீரான தேர்வு. முழு கால அளவு காலவரிசையில் இன்னும் தெரியும்.',
        'settings_calendar_span' => '<strong>பரவும் பட்டை</strong> &mdash; பணி அதன் தொடக்க தேதியிலிருந்து காலக்கெடு தேதி வரை ஓடும் ஒரே தொடர்ச்சியான பட்டையாக வரையப்படும்; ஒவ்வொரு வாரத்தின் முடிவிலும் அடுத்த வரிசைக்குச் செல்லும். பட்டைகள் ஒன்றோடொன்று மேலெழாதபடி தடங்களில் அடுக்கப்படும். அழகான கட்டத்தைவிட, வேலைகள் எவ்வளவு நேரம் எடுக்கின்றன, எவை ஒன்றையொன்று மேலெழுகின்றன என்பது முக்கியமெனில் சிறந்தது.',
        'settings_calendar_everyday' => '<strong>ஒவ்வொரு நாளும்</strong> &mdash; பணி உள்ளடக்கும் ஒவ்வொரு நாள் கட்டத்திலும் ஒரு சிப் திரும்பத் திரும்ப இடப்படும். மிகவும் முழுமையானது &mdash; எந்த நாளிலும் பணியைத் தவறவிட முடியாது &mdash; ஆனால் சில நீண்ட பணிகளே கட்டத்தை விரைவில் நிரப்பிவிடும்.',
        'settings_calendar_note' => 'எந்த முறையைத் தேர்ந்தெடுத்தாலும், காலக்கெடு தேதி <em>மட்டுமே</em> உள்ள (தொடக்க தேதி இல்லாத) பணி எப்போதும் அந்த தேதியில் ஒரே சிப்பாகத் தோன்றும் &mdash; உண்மையான தேதி <em>வரம்பு</em> எவ்வாறு வரையப்படுகிறது என்பதை மட்டுமே முறைகள் மாற்றுகின்றன. நாட்காட்டியே தனது கருவிப்பட்டியில் தற்போதைய முறையைக் காட்டும்; அதில் உள்ள <strong>Change</strong> இணைப்பு நேராக இந்தத் தாவலுக்குக் கொண்டுவரும்.',
        'settings_checklists_heading' => 'சரிபார்ப்புப் பட்டியல்கள்',
        'settings_checklists_body' => '<strong>Allow checklists on tasks</strong> என்பதை இயக்கினால், ஒவ்வொரு பணியும் துணைப் பணியும் <strong>சரிபார்ப்புப் பட்டியல்</strong> பிரிவைப் பெறும்: <em>பணிகள்</em> அல்லது <em>இரண்டும்</em> என்பதற்கு அமைக்கப்பட்ட சரிபார்ப்புப் பட்டியல்கள் தொகுதியிலிருந்து எந்தப் பட்டியலையும் இணைத்து, செல்லச் செல்ல அதன் படிகளைத் தேர்வு செய்யுங்கள். மதிப்பு கேட்கும் படியை மதிப்பு இல்லாமல் தேர்வு செய்ய முடியாது. இது இயல்பாக அணைந்திருக்கும். ஒரு பணி ஒன்றுக்கு மேற்பட்ட சரிபார்ப்புப் பட்டியல்களைக் கொண்டிருக்கலாம்; வரிசையை மாற்ற, ஒரு பட்டியலையோ அதற்குள் உள்ள படியையோ அதன் <strong>&#8942;&#8942;</strong> கைப்பிடியால் இழுக்கவும்.',
        'settings_checklists_standard' => '<strong>நிலையான</strong> சரிபார்ப்புப் பட்டியல் &mdash; கட்டாயப் படிகள் நிலுவையில் இருந்தாலும் பணியை முடிக்கலாம். முதலில் உங்களிடம் கேட்கப்படும்; யார் முடித்தார், எந்தப் படிகள் தவிர்க்கப்பட்டன என்பதைப் பணியின் வரலாறு பதிவு செய்யும்.',
        'settings_checklists_critical' => '<strong>முக்கியமான</strong> சரிபார்ப்புப் பட்டியல் (பூட்டு) &mdash; கட்டாயப் படிகள் முடியும் வரை பணியை முடிக்க முடியாது; நிலைப் பெட்டியிலிருந்தாலும், அட்டையை மூடப்பட்ட நெடுவரிசைக்கு இழுத்தாலும், துணைப் பணியைத் தேர்வு செய்தாலும், API வழியாகவும் இதுவே பொருந்தும்.',
        'settings_evidence_heading' => 'சான்று',
        'settings_evidence_body' => 'தணிக்கையாளர் படிக்கும் பதிவு குறித்த நான்கு தேர்வுகள். ஒவ்வொன்றும் இயல்பாக மென்மையான தேர்வில் இருக்கும்; எதைத் தேர்ந்தெடுத்தாலும், ஏற்கனவே பதிவானவை எதுவும் இழக்கப்படாது.',
        'settings_evidence_checklist' => '<strong>முடிக்கப்பட்ட பணியின் சரிபார்ப்புப் பட்டியலை மாற்றுதல்</strong> - <em>அனுமதிக்கப்பட்டு, பதிவு செய்யப்படும்</em> (எழுத்துப் பிழையைத் திருத்தலாம்; மாற்றம் அறிக்கையில் குறிக்கப்படும்) அல்லது <em>பணி மீண்டும் திறக்கப்படும் வரை மறுக்கப்படும்</em>.',
        'settings_evidence_delete' => '<strong>தொடரின் ஒரு நிகழ்வை நீக்குதல்</strong> - <em>அனுமதிக்கப்பட்டு, நீக்கப்பட்டதாக வைக்கப்படும்</em> (அதன் உறைந்த நகல் அறிக்கையில் இருக்கும்) அல்லது <em>அனுமதி இல்லை - அதற்குப் பதிலாகத் தவிர்க்கவும்</em>.',
        'settings_evidence_skip' => '<strong>தவிர்க்கப்பட்ட நிகழ்வு செல்லும் நிலை</strong> - உங்கள் மூடப்பட்ட நிலைகளில் ஒன்று; இயல்பாக உங்கள் வரிசையில் கடைசியானது, இது நிலையான நிறுவலில் <em>ரத்து செய்யப்பட்டது</em>.',
        'settings_evidence_access' => '<strong>சான்று அறிக்கையை யார் இயக்கலாம்</strong> - தொடர் பணியைக் காணக்கூடிய எவரும், அல்லது <em>Run the evidence report</em> கொண்ட பங்குகள் மட்டும்.',
        'settings_checklists_note' => 'டிக்கெட்டுகள் &rarr; அமைப்புகள் &rarr; சரிபார்ப்புப் பட்டியல்கள் என்பதன் கீழ் உள்ள நிறுவன அமைப்பு <strong>Block all</strong> பணிகளுக்கும் பொருந்தும். தொடர் பணி ஒவ்வொரு புதிய நிகழ்வுக்கும் தனது சரிபார்ப்புப் பட்டியல்களின் புதிய, தேர்வு செய்யப்படாத நகலைத் தரும். இதை அணைத்தால் பிரிவு மறைந்து, அமலாக்கமும் நிற்கும்; சரிபார்ப்புப் பட்டியலை அது ஒருபோதும் நீக்காது.',
        'settings_tags_heading' => 'குறிச்சொல் விருப்பங்கள்',
        'settings_tags_body' => 'குறிச்சொற்கள் தாவல் இரண்டு வேலைகளைச் செய்கிறது. மேல் பாதி <strong>குறிச்சொல் பட்டியல்</strong> &mdash; உங்கள் குழு பயன்படுத்தக்கூடிய குறிச்சொற்களைச் சேர்க்க, திருத்த, நீக்க, நிறம் மாற்ற (ஒவ்வொன்றும் வெறும் பெயரும் நிறமும்). கீழ் பாதி <strong>காட்சி விருப்பங்கள்</strong>, குறிச்சொல்லிடல் எவ்வாறு செயல்படும், குறிச்சொற்கள் எங்கே தோன்றும் என்பதை முடிவு செய்யும் ஐந்து மாற்றிகள்:',
        'settings_tags_allow' => '<strong>பணியிலிருந்து புதிய குறிச்சொற்களை அனுமதி</strong> (இயல்பாக அணைவு) &mdash; நிர்வகிக்கப்பட்டது அல்லது திறந்தது என்பதற்கான மாற்றி. அணைந்திருந்தால் குறிச்சொல் பட்டியல் நிலையான சொல்தொகுப்பு: பகுப்பாய்வாளர்கள் இருக்கும் குறிச்சொற்களை மட்டுமே தேர்ந்தெடுக்க முடியும், புதியவை இங்கே அமைப்புகளில் சேர்க்கப்படும் &mdash; Security அல்லது ISO போன்ற கட்டுப்படுத்தப்பட்ட தொகுப்புக்குச் சிறந்தது. இயக்கத்தில், பணியில் உள்ள குறிச்சொல் தேர்வி மூலம் பகுப்பாய்வாளர் அந்த இடத்திலேயே புதிய குறிச்சொல்லை தட்டச்சு செய்து உருவாக்கவும் முடியும்.',
        'settings_tags_chips' => '<strong>அட்டை சிப்புகள்</strong> &mdash; பலகை மற்றும் பட்டியல் அட்டைகளில் நிற குறிச்சொல் சிப்புகளைக் காட்டும். அட்டைகளை எளிமையாக வைத்திருக்க விரும்பினால் அணைக்கவும்.',
        'settings_tags_filter' => '<strong>பக்கப்பட்டி வடிகட்டி</strong> &mdash; பலகை/பட்டியல் பக்கப்பட்டியில் குறிச்சொல் கீழ்விரியைக் காட்டும்; அதனால் பார்வையை ஒரே குறிச்சொல்லுக்குச் சுருக்கலாம்.',
        'settings_tags_search' => '<strong>தேடல் பொருத்தம்</strong> &mdash; தேடல் பெட்டி பொருத்தும் விஷயங்களில் குறிச்சொல் பெயர்களையும் சேர்க்கும்; எனவே குறிச்சொல் பெயரைத் தட்டச்சு செய்தால் அதைக் கொண்ட ஒவ்வொரு பணியும் கிடைக்கும்.',
        'settings_tags_calendar' => '<strong>நாட்காட்டி &amp; காலவரிசை</strong> &mdash; நாட்காட்டி மற்றும் காலவரிசைக் காட்சிகளில் பணிப் பட்டைகளில் சிறிய குறிச்சொல் புள்ளிகளைக் காட்டும். அந்தக் காட்சிகள் தேதி சார்ந்தவை என்பதால் இயல்பாக அணைவு.',
        'settings_tags_note' => 'மாற்றிகள் ஒன்றையொன்று சாராதவை &mdash; எடுத்துக்காட்டாக, அட்டைகளில் குறிச்சொற்களை வைக்காமல் அவற்றால் வடிகட்டவும் தேடவும் செய்யலாம். குறிச்சொல் காட்சி மாற்றங்கள் அடுத்த முறை காட்சி ஏற்றப்படும்போது அமலுக்கு வரும்.',
        'tips_heading' => 'விரைவு குறிப்புகள்',
        'tips_intro' => 'இந்தத் தொகுதியில் வேகமாகச் செயல்பட உதவும் சில குறுக்குவழிகளும் பழக்கங்களும்.',
        'tip1' => '<strong>வலது கிளிக் வேகமானது.</strong> அட்டையைத் திறக்காமலே அதன் சூழல் மெனுவிலிருந்து மறு ஒதுக்கீடு அல்லது மறு முன்னுரிமை செய்யலாம்.',
        'tip2' => '<strong>விரைவாகச் சேர், பிறகு Enter.</strong> நெடுவரிசையின் + பொத்தானால் பணித் தலைப்பைப் பதிவு செய்து, விவரங்களைப் பின்னர் நிரப்புங்கள்.',
        'tip3' => '<strong>தேடல் உடனடியானது.</strong> நீங்கள் தட்டச்சு செய்யும்போதே வடிகட்டி, ஒவ்வொரு சொல்லையும் பொருத்தும் &mdash; காத்திருக்கவோ Enter அழுத்தவோ தேவையில்லை.',
        'tip4' => '<strong>கருப்பொருளுக்குக் குறிச்சொல்.</strong> நிலைகளைக் கடந்து வரும் எதற்கும் குறிச்சொற்களைப் பயன்படுத்துங்கள் &mdash; இணக்கம், பாதுகாப்பு, திட்டங்கள்.',
        'tip5' => '<strong>இரண்டு தேதிகள், இரண்டு காட்சிகள்.</strong> தொடக்க தேதியையும் காலக்கெடு தேதியையும் அமைத்தால், பணி நாட்காட்டியிலும் காலவரிசையிலும் தானாகவே வரையப்படும்.',
        'tip6' => '<strong>மூலத்தை இணைக்கவும்.</strong> பணி எந்த டிக்கெட் அல்லது மாற்றத்திலிருந்து வந்ததோ அதை இணைக்கவும்; சூழல் ஒரு கிளிக் தூரத்தில் இருக்கும்.',
        'tip7' => '<strong>பட்டையை இழுக்கவும்.</strong> காலவரிசையில், மறுஅட்டவணையிட பட்டையின் உடலையும், தொடக்க அல்லது காலக்கெடு தேதியை நேரடியாக அமைக்க ஏதேனும் ஓரத்தையும் இழுக்கவும் &mdash; பலகம் தேவையில்லை.',
        'tip8' => '<strong>உங்கள் சொந்த அட்டவணையை உருவாக்குங்கள்.</strong> அட்டவணைக் காட்சியில் எந்த நெடுவரிசைகள் தெரிய வேண்டும் எனத் தேர்ந்தெடுத்து, விரும்பிய வரிசைக்கு இழுத்து, வரிசைப்படுத்தி வடிகட்டுங்கள் &mdash; உங்கள் அமைப்பு ஒவ்வொரு பகுப்பாய்வாளருக்கும் தனியாகச் சேமிக்கப்படும்.',
    ],
