        'stop' => 'தொடர்வதை நிறுத்து',
        'preview' => 'முன்னோட்டம்',
        'preview_none' => 'இந்த அமைப்புகள் இன்னொரு நிகழ்வை உருவாக்காது, எனவே இனி எதுவும் உருவாக்கப்படாது. முடிவை அல்லது நீங்கள் தேர்ந்த நாளைச் சரிபார்க்கவும்.',
        'preview_heading' => 'இந்தத் தொடர் பணியின் ஒவ்வொரு நிகழ்வும்',
